/**
 * plantillas-dashboard.ts — ficheros del Dashboard (editor + creador de
 * cards para redes sociales) que se generan tal cual en cada medio nuevo.
 * Generado automáticamente a partir de plantillas fuente; no editar a mano
 * las cadenas de abajo, edita las fuentes y regenera.
 */
import type { Fichero } from './plantillas';

export function construirDashboard(): Fichero[] {
  return [
  { path: "src/components/Editor/nodosPropios.ts", content: "/**\n * Nodos propios del editor para TipTap: Callout, ElDato y Cita.\n * Cada uno se traduce a su componente MDX homónimo (ver tiptapToMdx.ts).\n */\nimport { Node, mergeAttributes } from '@tiptap/core';\n\n/* ============================================================\n   CALLOUT — <Callout tipo=\"lectura|contexto\">…</Callout>\n   ============================================================ */\nexport const Callout = Node.create({\n  name: 'callout',\n  group: 'block',\n  content: 'block+',\n  defining: true,\n\n  addAttributes() {\n    return {\n      tipo: {\n        default: 'contexto',\n        parseHTML: (el) => el.getAttribute('data-tipo') || 'contexto',\n        renderHTML: (attrs) => ({ 'data-tipo': attrs.tipo }),\n      },\n    };\n  },\n\n  parseHTML() {\n    return [{ tag: 'div[data-callout]' }];\n  },\n\n  renderHTML({ HTMLAttributes }) {\n    return ['div', mergeAttributes(HTMLAttributes, { 'data-callout': '', class: 'ed-callout' }), 0];\n  },\n\n  addCommands() {\n    return {\n      setCallout:\n        (tipo = 'contexto') =>\n        ({ commands }: any) =>\n          commands.wrapIn(this.name, { tipo }),\n    } as any;\n  },\n});\n\n/* ============================================================\n   ELDATO — <ElDato cifra=\"\" unidad=\"\" fuente=\"\">…</ElDato>\n   ============================================================ */\nexport const ElDato = Node.create({\n  name: 'elDato',\n  group: 'block',\n  content: 'block+',\n  defining: true,\n\n  addAttributes() {\n    return {\n      cifra: { default: '', parseHTML: (el) => el.getAttribute('data-cifra') || '', renderHTML: (a) => ({ 'data-cifra': a.cifra }) },\n      unidad: { default: '', parseHTML: (el) => el.getAttribute('data-unidad') || '', renderHTML: (a) => ({ 'data-unidad': a.unidad }) },\n      fuente: { default: '', parseHTML: (el) => el.getAttribute('data-fuente') || '', renderHTML: (a) => ({ 'data-fuente': a.fuente }) },\n    };\n  },\n\n  parseHTML() {\n    return [{ tag: 'div[data-eldato]' }];\n  },\n\n  renderHTML({ HTMLAttributes, node }) {\n    const cifra = node.attrs.cifra || '0';\n    const unidad = node.attrs.unidad || '';\n    return [\n      'div',\n      mergeAttributes(HTMLAttributes, { 'data-eldato': '', class: 'ed-eldato' }),\n      ['div', { class: 'ed-eldato-cifra', contenteditable: 'false' }, cifra + (unidad ? ' ' + unidad : '')],\n      ['div', { class: 'ed-eldato-hueco' }, 0],\n    ];\n  },\n\n  addCommands() {\n    return {\n      insertElDato:\n        (attrs: { cifra: string; unidad: string; fuente: string }) =>\n        ({ commands }: any) =>\n          commands.insertContent({\n            type: this.name,\n            attrs,\n            content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Contexto del dato…' }] }],\n          }),\n    } as any;\n  },\n});\n\n/* ============================================================\n   CITA — <Cita autor=\"\" cargo=\"\">…</Cita>\n   ============================================================ */\nexport const Cita = Node.create({\n  name: 'cita',\n  group: 'block',\n  content: 'block+',\n  defining: true,\n\n  addAttributes() {\n    return {\n      autor: { default: '', parseHTML: (el) => el.getAttribute('data-autor') || '', renderHTML: (a) => ({ 'data-autor': a.autor }) },\n      cargo: { default: '', parseHTML: (el) => el.getAttribute('data-cargo') || '', renderHTML: (a) => ({ 'data-cargo': a.cargo }) },\n    };\n  },\n\n  parseHTML() {\n    return [{ tag: 'div[data-cita]' }];\n  },\n\n  renderHTML({ HTMLAttributes }) {\n    return ['div', mergeAttributes(HTMLAttributes, { 'data-cita': '', class: 'ed-cita' }), 0];\n  },\n\n  addCommands() {\n    return {\n      insertCita:\n        (attrs: { autor: string; cargo: string }) =>\n        ({ commands }: any) =>\n          commands.insertContent({\n            type: this.name,\n            attrs,\n            content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Cita textual…' }] }],\n          }),\n    } as any;\n  },\n});\n" },
  { path: "src/components/Editor/tiptapToMdx.ts", content: "/**\n * tiptapToMdx — convierte el documento de TipTap (JSON ProseMirror) a MDX.\n *\n * Componentes propios que emite (deben existir en src/components/articulo/):\n *   <Figura src alt pie />         imagen con pie de foto\n *   <Callout tipo=\"…\">…</Callout>  avisos/lecturas\n *   <ElDato cifra unidad fuente>…</ElDato>  cifra destacada\n *   <Cita autor cargo>…</Cita>     cita atribuida\n */\n\nexport interface TipTapNode {\n  type: string;\n  attrs?: Record<string, any>;\n  content?: TipTapNode[];\n  marks?: { type: string; attrs?: Record<string, any> }[];\n  text?: string;\n}\n\nfunction escapeAttr(s: string): string {\n  return String(s ?? '').replace(/\"/g, '&quot;');\n}\n\nfunction applyMarks(text: string, marks?: TipTapNode['marks']): string {\n  if (!marks || marks.length === 0) return text;\n  let out = text;\n  const hasCode = marks.some((m) => m.type === 'code');\n  if (hasCode) return '`' + text + '`';\n  for (const m of marks) {\n    if (m.type === 'bold') out = '**' + out + '**';\n    else if (m.type === 'italic') out = '*' + out + '*';\n    else if (m.type === 'strike') out = '~~' + out + '~~';\n    else if (m.type === 'link') out = '[' + out + '](' + (m.attrs?.href ?? '') + ')';\n  }\n  return out;\n}\n\nfunction inline(content?: TipTapNode[]): string {\n  if (!content) return '';\n  return content\n    .map((n) => {\n      if (n.type === 'text') return applyMarks(n.text ?? '', n.marks);\n      if (n.type === 'hardBreak') return '  \\n';\n      return blockToMdx(n);\n    })\n    .join('');\n}\n\nfunction tableToMdx(node: TipTapNode): string {\n  const rows = node.content ?? [];\n  if (rows.length === 0) return '';\n  const renderRow = (row: TipTapNode) =>\n    '| ' +\n    (row.content ?? [])\n      .map((cell) => inline(cell.content?.[0]?.content).trim() || ' ')\n      .join(' | ') +\n    ' |';\n\n  const firstRow = rows[0];\n  const colCount = (firstRow.content ?? []).length;\n  const header = renderRow(firstRow);\n  const sep = '| ' + Array(colCount).fill('---').join(' | ') + ' |';\n  const body = rows.slice(1).map(renderRow).join('\\n');\n  return [header, sep, body].filter(Boolean).join('\\n');\n}\n\nfunction blockToMdx(node: TipTapNode): string {\n  switch (node.type) {\n    case 'heading': {\n      const lvl = Math.min(Math.max(node.attrs?.level ?? 1, 1), 6);\n      return '#'.repeat(lvl) + ' ' + inline(node.content);\n    }\n    case 'paragraph':\n      return inline(node.content);\n\n    case 'bulletList':\n      return (node.content ?? []).map((li) => listItemToMdx(li, '- ')).join('\\n');\n\n    case 'orderedList':\n      return (node.content ?? []).map((li, i) => listItemToMdx(li, (i + 1) + '. ')).join('\\n');\n\n    case 'blockquote':\n      return (node.content ?? [])\n        .map((n) => blockToMdx(n))\n        .join('\\n')\n        .split('\\n')\n        .map((l) => '> ' + l)\n        .join('\\n');\n\n    case 'codeBlock': {\n      const lang = node.attrs?.language ?? '';\n      const code = (node.content ?? []).map((c) => c.text ?? '').join('');\n      const fence = '```';\n      return fence + lang + '\\n' + code + '\\n' + fence;\n    }\n\n    case 'horizontalRule':\n      return '---';\n\n    case 'image': {\n      const src = node.attrs?.src ?? '';\n      const alt = node.attrs?.alt ?? '';\n      const pie = node.attrs?.title ?? node.attrs?.pie ?? '';\n      if (pie) {\n        return '<Figura src=\"' + escapeAttr(src) + '\" alt=\"' + escapeAttr(alt) + '\" pie=\"' + escapeAttr(pie) + '\" />';\n      }\n      return '![' + alt + '](' + src + ')';\n    }\n\n    case 'table':\n      return tableToMdx(node);\n\n    case 'callout': {\n      const tipo = node.attrs?.tipo ?? 'contexto';\n      const inner = (node.content ?? []).map((n) => blockToMdx(n)).join('\\n\\n');\n      return '<Callout tipo=\"' + escapeAttr(tipo) + '\">\\n' + inner + '\\n</Callout>';\n    }\n\n    case 'elDato': {\n      const cifra = node.attrs?.cifra ?? '';\n      const unidad = node.attrs?.unidad ?? '';\n      const fuente = node.attrs?.fuente ?? '';\n      const inner = (node.content ?? []).map((n) => blockToMdx(n)).join('\\n\\n');\n      return (\n        '<ElDato cifra=\"' + escapeAttr(cifra) + '\" unidad=\"' + escapeAttr(unidad) + '\" fuente=\"' + escapeAttr(fuente) + '\">\\n' +\n        inner +\n        '\\n</ElDato>'\n      );\n    }\n\n    case 'cita': {\n      const autor = node.attrs?.autor ?? '';\n      const cargo = node.attrs?.cargo ?? '';\n      const inner = (node.content ?? []).map((n) => blockToMdx(n)).join('\\n\\n');\n      return '<Cita autor=\"' + escapeAttr(autor) + '\" cargo=\"' + escapeAttr(cargo) + '\">\\n' + inner + '\\n</Cita>';\n    }\n\n    default:\n      return inline(node.content);\n  }\n}\n\nfunction listItemToMdx(li: TipTapNode, marker: string): string {\n  const blocks = li.content ?? [];\n  const pad = ' '.repeat(marker.length);\n  const parts = blocks.map((b, i) => {\n    const md = blockToMdx(b);\n    if (i === 0) return marker + md;\n    return md\n      .split('\\n')\n      .map((l) => pad + l)\n      .join('\\n');\n  });\n  return parts.join('\\n');\n}\n\nexport function tiptapToMdx(doc: TipTapNode): string {\n  if (!doc || doc.type !== 'doc') return '';\n  return (doc.content ?? [])\n    .map((n) => blockToMdx(n))\n    .filter((s) => s !== '')\n    .join('\\n\\n')\n    .replace(/\\n{3,}/g, '\\n\\n')\n    .trim();\n}\n" },
  { path: "src/components/Editor/mdxToTiptap.ts", content: "/**\n * mdxToTiptap — convierte el cuerpo MDX de un artículo a documento TipTap.\n * Es la inversa de tiptapToMdx: permite abrir artículos ya escritos.\n */\n\ninterface Nodo {\n  type: string;\n  attrs?: Record<string, any>;\n  content?: Nodo[];\n  marks?: { type: string; attrs?: Record<string, any> }[];\n  text?: string;\n}\n\nfunction parseInline(texto: string): Nodo[] {\n  const nodos: Nodo[] = [];\n  let resto = texto;\n\n  const patrones: { re: RegExp; crear: (m: RegExpMatchArray) => Nodo }[] = [\n    { re: /^`([^`]+)`/, crear: (m) => ({ type: 'text', text: m[1], marks: [{ type: 'code' }] }) },\n    { re: /^\\*\\*([^*]+)\\*\\*/, crear: (m) => ({ type: 'text', text: m[1], marks: [{ type: 'bold' }] }) },\n    { re: /^\\*([^*]+)\\*/, crear: (m) => ({ type: 'text', text: m[1], marks: [{ type: 'italic' }] }) },\n    { re: /^~~([^~]+)~~/, crear: (m) => ({ type: 'text', text: m[1], marks: [{ type: 'strike' }] }) },\n    {\n      re: /^\\[([^\\]]+)\\]\\(([^)]+)\\)/,\n      crear: (m) => ({ type: 'text', text: m[1], marks: [{ type: 'link', attrs: { href: m[2] } }] }),\n    },\n  ];\n\n  let buffer = '';\n  while (resto.length > 0) {\n    let encontrado = false;\n    for (const p of patrones) {\n      const m = resto.match(p.re);\n      if (m) {\n        if (buffer) {\n          nodos.push({ type: 'text', text: buffer });\n          buffer = '';\n        }\n        nodos.push(p.crear(m));\n        resto = resto.slice(m[0].length);\n        encontrado = true;\n        break;\n      }\n    }\n    if (!encontrado) {\n      buffer += resto[0];\n      resto = resto.slice(1);\n    }\n  }\n  if (buffer) nodos.push({ type: 'text', text: buffer });\n  return nodos.length ? nodos : [];\n}\n\nfunction parrafo(texto: string): Nodo {\n  const contenido = parseInline(texto);\n  return contenido.length ? { type: 'paragraph', content: contenido } : { type: 'paragraph' };\n}\n\nfunction parseAtributos(linea: string): Record<string, string> {\n  const attrs: Record<string, string> = {};\n  const re = /(\\w+)=\"([^\"]*)\"/g;\n  let m;\n  while ((m = re.exec(linea)) !== null) attrs[m[1]] = m[2];\n  return attrs;\n}\n\nfunction tomarBloque(lineas: string[], i: number, cierre: string): { dentro: string[]; i: number } {\n  const dentro: string[] = [];\n  i++;\n  while (i < lineas.length && !lineas[i].trim().startsWith(cierre)) {\n    dentro.push(lineas[i]);\n    i++;\n  }\n  i++;\n  return { dentro, i };\n}\n\nexport function mdxToTiptap(mdx: string): Nodo {\n  const lineas = mdx.split('\\n');\n  const content: Nodo[] = [];\n  let i = 0;\n\n  while (i < lineas.length) {\n    const linea = lineas[i];\n    const t = linea.trim();\n\n    if (!t) {\n      i++;\n      continue;\n    }\n\n    if (/^---+$/.test(t)) {\n      content.push({ type: 'horizontalRule' });\n      i++;\n      continue;\n    }\n\n    const h = t.match(/^(#{1,6})\\s+(.*)$/);\n    if (h) {\n      content.push({ type: 'heading', attrs: { level: h[1].length }, content: parseInline(h[2]) });\n      i++;\n      continue;\n    }\n\n    if (t.startsWith('```')) {\n      const lang = t.slice(3).trim();\n      const codigo: string[] = [];\n      i++;\n      while (i < lineas.length && !lineas[i].trim().startsWith('```')) {\n        codigo.push(lineas[i]);\n        i++;\n      }\n      i++;\n      const texto = codigo.join('\\n');\n      content.push({ type: 'codeBlock', attrs: { language: lang || null }, content: texto ? [{ type: 'text', text: texto }] : [] });\n      continue;\n    }\n\n    if (t.startsWith('<Figura')) {\n      const a = parseAtributos(t);\n      content.push({ type: 'image', attrs: { src: a.src ?? '', alt: a.alt ?? '', title: a.pie || null } });\n      i++;\n      continue;\n    }\n\n    if (t.startsWith('<Callout')) {\n      const a = parseAtributos(t);\n      const { dentro, i: i2 } = tomarBloque(lineas, i, '</Callout>');\n      i = i2;\n      const sub = mdxToTiptap(dentro.join('\\n'));\n      content.push({ type: 'callout', attrs: { tipo: a.tipo ?? 'contexto' }, content: sub.content?.length ? sub.content : [{ type: 'paragraph' }] });\n      continue;\n    }\n\n    if (t.startsWith('<ElDato')) {\n      const a = parseAtributos(t);\n      const { dentro, i: i2 } = tomarBloque(lineas, i, '</ElDato>');\n      i = i2;\n      const sub = mdxToTiptap(dentro.join('\\n'));\n      content.push({\n        type: 'elDato',\n        attrs: { cifra: a.cifra ?? '', unidad: a.unidad ?? '', fuente: a.fuente ?? '' },\n        content: sub.content?.length ? sub.content : [{ type: 'paragraph' }],\n      });\n      continue;\n    }\n\n    if (t.startsWith('<Cita')) {\n      const a = parseAtributos(t);\n      const { dentro, i: i2 } = tomarBloque(lineas, i, '</Cita>');\n      i = i2;\n      const sub = mdxToTiptap(dentro.join('\\n'));\n      content.push({\n        type: 'cita',\n        attrs: { autor: a.autor ?? '', cargo: a.cargo ?? '' },\n        content: sub.content?.length ? sub.content : [{ type: 'paragraph' }],\n      });\n      continue;\n    }\n\n    if (t.startsWith('>')) {\n      const cita: string[] = [];\n      while (i < lineas.length && lineas[i].trim().startsWith('>')) {\n        cita.push(lineas[i].trim().replace(/^>\\s?/, ''));\n        i++;\n      }\n      const sub = mdxToTiptap(cita.join('\\n'));\n      content.push({ type: 'blockquote', content: sub.content?.length ? sub.content : [{ type: 'paragraph' }] });\n      continue;\n    }\n\n    if (t.startsWith('|') && i + 1 < lineas.length && /^\\|[\\s:|-]+\\|$/.test(lineas[i + 1].trim())) {\n      const filas: string[][] = [];\n      filas.push(t.split('|').slice(1, -1).map((c) => c.trim()));\n      i += 2;\n      while (i < lineas.length && lineas[i].trim().startsWith('|')) {\n        filas.push(lineas[i].trim().split('|').slice(1, -1).map((c) => c.trim()));\n        i++;\n      }\n      content.push({\n        type: 'table',\n        content: filas.map((fila, idx) => ({\n          type: 'tableRow',\n          content: fila.map((celda) => ({ type: idx === 0 ? 'tableHeader' : 'tableCell', content: [parrafo(celda)] })),\n        })),\n      });\n      continue;\n    }\n\n    const esVinneta = /^[-*+]\\s+/.test(t);\n    const esNumerada = /^\\d+\\.\\s+/.test(t);\n    if (esVinneta || esNumerada) {\n      const items: Nodo[] = [];\n      const re = esVinneta ? /^[-*+]\\s+/ : /^\\d+\\.\\s+/;\n      while (i < lineas.length) {\n        const li = lineas[i].trim();\n        if (!re.test(li)) break;\n        items.push({ type: 'listItem', content: [parrafo(li.replace(re, ''))] });\n        i++;\n      }\n      content.push({ type: esVinneta ? 'bulletList' : 'orderedList', content: items });\n      continue;\n    }\n\n    const parr: string[] = [];\n    while (i < lineas.length && lineas[i].trim() !== '') {\n      const l = lineas[i].trim();\n      if (\n        /^(#{1,6})\\s/.test(l) || l.startsWith('```') || l.startsWith('>') ||\n        l.startsWith('<Figura') || l.startsWith('<Callout') || l.startsWith('<ElDato') || l.startsWith('<Cita') ||\n        /^---+$/.test(l) || /^[-*+]\\s/.test(l) || /^\\d+\\.\\s/.test(l) || l.startsWith('|')\n      ) break;\n      parr.push(l);\n      i++;\n    }\n    if (parr.length) content.push(parrafo(parr.join(' ')));\n    else i++;\n  }\n\n  return { type: 'doc', content: content.length ? content : [{ type: 'paragraph' }] };\n}\n" },
  { path: "src/components/Editor/frontmatter.ts", content: "/**\n * frontmatter — construye y valida el frontmatter YAML del artículo.\n * Alineado con el schema Zod de content.config.ts.\n */\n\nexport interface Meta {\n  titulo: string;\n  descripcion: string;\n  seccion: string;\n  fecha: string;\n  autor: string;\n  fuente?: string;\n  borrador: boolean;\n  etiquetas: string[];\n  imagen?: string;\n  imagenCredito?: string;\n}\n\nfunction yamlStr(s: string): string {\n  if (/[:#[\\]{}\"'`>|&*!%@,]/.test(s)) return '\"' + s.replace(/\"/g, '\\\\\"') + '\"';\n  return s;\n}\n\nexport function buildFrontmatter(m: Meta, nombreMedio: string): string {\n  const titulo = m.titulo?.trim() || 'Sin título';\n  let fm = '---\\n';\n  fm += 'titulo: ' + yamlStr(titulo) + '\\n';\n  fm += 'descripcion: ' + yamlStr(m.descripcion?.trim() ?? '') + '\\n';\n  fm += 'seccion: ' + yamlStr(m.seccion) + '\\n';\n  fm += 'fecha: ' + m.fecha + '\\n';\n  fm += 'autor: ' + yamlStr(m.autor?.trim() || nombreMedio) + '\\n';\n  if (m.fuente?.trim()) fm += 'fuente: ' + yamlStr(m.fuente.trim()) + '\\n';\n  fm += 'borrador: ' + (!!m.borrador) + '\\n';\n  fm += 'etiquetas: [' + (m.etiquetas ?? []).map(yamlStr).join(', ') + ']\\n';\n  if (m.imagen?.trim()) fm += 'imagen: ' + yamlStr(m.imagen.trim()) + '\\n';\n  if (m.imagenCredito?.trim()) fm += 'imagenCredito: ' + yamlStr(m.imagenCredito.trim()) + '\\n';\n  fm += '---\\n';\n  return fm;\n}\n\nexport function slugify(s: string): string {\n  return String(s ?? '')\n    .toLowerCase()\n    .normalize('NFD')\n    .replace(/[\\u0300-\\u036f]/g, '')\n    .replace(/[^a-z0-9\\s-]/g, '')\n    .trim()\n    .replace(/\\s+/g, '-')\n    .replace(/-+/g, '-')\n    .slice(0, 60);\n}\n\nexport interface Aviso {\n  campo: string;\n  msg: string;\n  grave: boolean;\n}\n\nexport function validarMeta(m: Meta, cuerpoVacio: boolean): Aviso[] {\n  const a: Aviso[] = [];\n  const t = m.titulo?.trim() ?? '';\n  if (!t) a.push({ campo: 'titulo', msg: 'Falta el título (H1).', grave: true });\n  else if (t.length > 110) a.push({ campo: 'titulo', msg: 'Título excede 110 car. (' + t.length + ').', grave: true });\n\n  const d = m.descripcion?.trim() ?? '';\n  if (!d) a.push({ campo: 'descripcion', msg: 'Falta la descripción.', grave: true });\n  else if (d.length > 200) a.push({ campo: 'descripcion', msg: 'Descripción excede 200 car. (' + d.length + ').', grave: true });\n  else if (d.length < 140 || d.length > 160) a.push({ campo: 'descripcion', msg: 'Descripción ' + d.length + ' car. (ideal SEO 140-160).', grave: false });\n\n  if (!m.fecha) a.push({ campo: 'fecha', msg: 'Falta la fecha.', grave: true });\n  if (!m.autor?.trim()) a.push({ campo: 'autor', msg: 'Falta el autor.', grave: true });\n  if ((m.etiquetas ?? []).length < 2) a.push({ campo: 'etiquetas', msg: 'Menos de 2 etiquetas (alimentan el enlazado).', grave: false });\n  if (cuerpoVacio) a.push({ campo: 'cuerpo', msg: 'El artículo está vacío.', grave: true });\n\n  return a;\n}\n" },
  { path: "src/components/Editor/analisis.ts", content: "/**\n * analisis — chequeo de voz editorial + métricas SEO.\n * Sin dependencias: se ejecuta sobre el texto plano y la meta del artículo.\n *\n * Las reglas de voz son antipatrones genéricos de cualquier medio serio,\n * no específicos de una temática: autobombo, condescendencia, sentencias\n * sin apoyo y apelación a autoridad personal en vez de datos.\n */\n\nexport interface AvisoVoz {\n  q: string;\n  why: string;\n  frag: string;\n  hard: boolean;\n}\n\nconst REGLAS_VOZ: { re: RegExp; q: string; why: string; hard: boolean }[] = [\n  {\n    re: /a diferencia de (?:la prensa|otros medios|la competencia)|donde otros no llegan|lo que otros no cuentan|por eso lo contamos nosotros|aquí es donde/i,\n    q: 'Autobombo',\n    why: 'El valor se demuestra explicando bien. Borra la comparación con \"otros\".',\n    hard: true,\n  },\n  {\n    re: /como (?:todos )?saben|como es evidente|obviamente cualquiera|a estas alturas nadie/i,\n    q: 'Suficiencia',\n    why: 'Condescendencia al lector. Explica, no des por sabido con superioridad.',\n    hard: false,\n  },\n  {\n    re: /yo ya lo sabía|siempre lo dije|te lo dije|como predije/i,\n    q: 'Autoridad personal',\n    why: '\"Lo he comprobado\" gana a \"yo ya lo sabía\". Apóyalo en un dato o pásalo a apuesta.',\n    hard: false,\n  },\n  {\n    re: /está claro que|sin duda alguna|es obvio que|indudablemente|no cabe duda/i,\n    q: 'Sentencia',\n    why: '¿Dato o lectura? Si es opinión, márcala como tal en un Callout.',\n    hard: false,\n  },\n];\n\nexport function chequeoVoz(texto: string): AvisoVoz[] {\n  const hits: AvisoVoz[] = [];\n  for (const r of REGLAS_VOZ) {\n    const m = texto.match(r.re);\n    if (m) hits.push({ q: r.q, why: r.why, frag: m[0], hard: r.hard });\n  }\n  return hits;\n}\n\nexport interface MetricaSeo {\n  estado: 'ok' | 'warn' | 'muted';\n  texto: string;\n}\n\nexport interface SeoInput {\n  titulo: string;\n  descripcion: string;\n  cuerpo: string;\n  etiquetas: string[];\n  enlacesInternos: number;\n  enlacesExternos: number;\n  imagenesSinAlt: number;\n  imagenesTotal: number;\n  imagenSocial?: string;\n}\n\nexport function legibilidad(cuerpo: string): { score: number; nivel: string } {\n  const palabras = cuerpo.trim().split(/\\s+/).filter(Boolean);\n  const frases = cuerpo.split(/[.!?]+/).filter((s) => s.trim().length > 0);\n  const silabas = palabras.reduce((acc, p) => acc + contarSilabas(p), 0);\n  const P = palabras.length || 1;\n  const F = frases.length || 1;\n  const score = 206.84 - 60 * (silabas / P) - 102 * (F / P);\n  const s = Math.max(0, Math.min(100, Math.round(score)));\n  let nivel = 'muy difícil';\n  if (s >= 90) nivel = 'muy fácil';\n  else if (s >= 80) nivel = 'fácil';\n  else if (s >= 70) nivel = 'algo fácil';\n  else if (s >= 60) nivel = 'normal';\n  else if (s >= 50) nivel = 'algo difícil';\n  else if (s >= 30) nivel = 'difícil';\n  return { score: s, nivel };\n}\n\nfunction contarSilabas(palabra: string): number {\n  const p = palabra.toLowerCase().replace(/[^a-záéíóúüñ]/g, '');\n  if (!p) return 0;\n  const grupos = p.match(/[aeiouáéíóúü]+/g);\n  return Math.max(1, grupos ? grupos.length : 1);\n}\n\nexport function metricasSeo(inp: SeoInput): MetricaSeo[] {\n  const rows: MetricaSeo[] = [];\n  const d = inp.descripcion?.length ?? 0;\n  rows.push(\n    d >= 140 && d <= 160\n      ? { estado: 'ok', texto: 'Meta description en rango (' + d + ')' }\n      : { estado: 'warn', texto: 'Meta description ' + d + ' car. (ideal 140-160)' }\n  );\n\n  const palabras = inp.cuerpo.trim().split(/\\s+/).filter(Boolean).length;\n  rows.push(\n    palabras >= 300\n      ? { estado: 'ok', texto: palabras + ' palabras' }\n      : { estado: 'warn', texto: palabras + ' palabras (Google premia +300 en piezas de fondo)' }\n  );\n\n  rows.push(\n    inp.enlacesInternos >= 1\n      ? { estado: 'ok', texto: inp.enlacesInternos + ' enlace(s) interno(s)' }\n      : { estado: 'warn', texto: 'Sin enlaces internos — añade 1-3' }\n  );\n  rows.push(\n    inp.enlacesExternos >= 1\n      ? { estado: 'ok', texto: inp.enlacesExternos + ' enlace(s) externo(s) (fuentes citadas)' }\n      : { estado: 'muted', texto: 'Sin enlaces externos' }\n  );\n\n  rows.push(\n    inp.etiquetas.length >= 2\n      ? { estado: 'ok', texto: inp.etiquetas.length + ' etiquetas' }\n      : { estado: 'warn', texto: 'Menos de 2 etiquetas' }\n  );\n\n  if (inp.imagenesTotal > 0) {\n    rows.push(\n      inp.imagenesSinAlt === 0\n        ? { estado: 'ok', texto: inp.imagenesTotal + ' imagen(es), todas con alt' }\n        : { estado: 'warn', texto: inp.imagenesSinAlt + ' imagen(es) sin alt (accesibilidad + SEO)' }\n    );\n  }\n\n  rows.push(\n    inp.imagenSocial\n      ? { estado: 'ok', texto: 'Imagen social (Open Graph) definida' }\n      : { estado: 'warn', texto: 'Sin imagen social — mala previsualización al compartir' }\n  );\n\n  const leg = legibilidad(inp.cuerpo);\n  rows.push({ estado: leg.score >= 50 ? 'ok' : 'warn', texto: 'Legibilidad: ' + leg.nivel + ' (' + leg.score + '/100)' });\n\n  return rows;\n}\n" },
  { path: "src/components/Editor/pexels.ts", content: "/**\n * pexels — cliente mínimo de la API de Pexels para el selector de imagen social.\n *\n * Obligaciones de la API de Pexels (van en sus términos):\n *   - Mostrar un enlace visible a Pexels cuando se usa la API.\n *   - Acreditar al fotógrafo con enlace a la foto.\n * El editor las cumple automáticamente al insertar el crédito.\n *\n * La clave se guarda en localStorage (herramienta interna, uso local).\n */\n\nconst CLAVE_KEY = 'editor:pexelsKey';\n\nexport interface FotoPexels {\n  id: number;\n  alt: string;\n  urlFoto: string;\n  fotografo: string;\n  fotografoUrl: string;\n  src: {\n    landscape: string;\n    large: string;\n    medium: string;\n    tiny: string;\n  };\n  colorMedio: string;\n}\n\nexport function getClave(): string {\n  try {\n    return localStorage.getItem(CLAVE_KEY) ?? '';\n  } catch {\n    return '';\n  }\n}\n\nexport function setClave(clave: string): void {\n  try {\n    localStorage.setItem(CLAVE_KEY, clave.trim());\n  } catch {}\n}\n\nexport interface ResultadoBusqueda {\n  ok: boolean;\n  fotos: FotoPexels[];\n  error?: string;\n}\n\nexport async function buscarFotos(query: string, pagina = 1): Promise<ResultadoBusqueda> {\n  const clave = getClave();\n  if (!clave) {\n    return { ok: false, fotos: [], error: 'Falta la clave de API de Pexels.' };\n  }\n  const url =\n    'https://api.pexels.com/v1/search?query=' + encodeURIComponent(query) +\n    '&orientation=landscape&per_page=15&page=' + pagina;\n\n  try {\n    const res = await fetch(url, { headers: { Authorization: clave } });\n    if (res.status === 401) return { ok: false, fotos: [], error: 'Clave de Pexels inválida.' };\n    if (res.status === 429) return { ok: false, fotos: [], error: 'Límite de peticiones alcanzado (200/hora). Espera un poco.' };\n    if (!res.ok) return { ok: false, fotos: [], error: 'Error de Pexels (' + res.status + ').' };\n    const data = await res.json();\n    const fotos: FotoPexels[] = (data.photos ?? []).map((p: any) => ({\n      id: p.id,\n      alt: p.alt ?? '',\n      urlFoto: p.url ?? '',\n      fotografo: p.photographer ?? '',\n      fotografoUrl: p.photographer_url ?? '',\n      src: {\n        landscape: p.src?.landscape ?? '',\n        large: p.src?.large ?? '',\n        medium: p.src?.medium ?? '',\n        tiny: p.src?.tiny ?? '',\n      },\n      colorMedio: p.avg_color ?? '#161b22',\n    }));\n    return { ok: true, fotos };\n  } catch (e: any) {\n    return { ok: false, fotos: [], error: 'No se pudo conectar con Pexels: ' + (e?.message ?? '') };\n  }\n}\n\nexport function creditoTexto(f: FotoPexels): string {\n  return 'Foto de ' + f.fotografo + ' en Pexels';\n}\n" },
  { path: "src/components/Editor/Editor.tsx", content: "/**\n * Editor — editor WYSIWYG basado en TipTap para artículos MDX.\n *\n * Isla React montada desde src/pages/dashboard.astro (client:only=\"react\").\n * Recibe la lista de artículos (para enlazado interno) y las secciones.\n */\nimport { useEditor, EditorContent } from '@tiptap/react';\nimport { StarterKit } from '@tiptap/starter-kit';\nimport { Image } from '@tiptap/extension-image';\nimport { Table } from '@tiptap/extension-table';\nimport { TableRow } from '@tiptap/extension-table-row';\nimport { TableCell } from '@tiptap/extension-table-cell';\nimport { TableHeader } from '@tiptap/extension-table-header';\nimport { Placeholder } from '@tiptap/extension-placeholder';\nimport { useEffect, useMemo, useRef, useState, useCallback } from 'react';\n\nimport { tiptapToMdx } from './tiptapToMdx';\nimport { mdxToTiptap } from './mdxToTiptap';\nimport { buildFrontmatter, slugify, validarMeta, type Meta } from './frontmatter';\nimport { chequeoVoz, metricasSeo } from './analisis';\nimport { Callout, ElDato, Cita } from './nodosPropios';\nimport { buscarFotos, getClave, setClave, creditoTexto, type FotoPexels } from './pexels';\nimport { NOMBRE_MEDIO } from '../../lib/medio';\nimport './editor.css';\n\nconst styles: Record<string, string> = {\n  counterWarn: 'ed-counterWarn', editorArea: 'ed-editorArea', mdxPreview: 'ed-mdxPreview',\n  counterBad: 'ed-counterBad', validation: 'ed-validation', counterOk: 'ed-counterOk',\n  voiceItem: 'ed-voiceItem', voiceHard: 'ed-voiceHard', seo_muted: 'ed-seo_muted',\n  modalHead: 'ed-modalHead', modalBody: 'ed-modalBody', btnGhost: 'ed-btnGhost',\n  tagInput: 'ed-tagInput', voiceWhy: 'ed-voiceWhy', seo_warn: 'ed-seo_warn',\n  primary: 'ed-primary', colMain: 'ed-colMain', colSide: 'ed-colSide', toolbar: 'ed-toolbar',\n  counter: 'ed-counter', tagsBox: 'ed-tagsBox', toggles: 'ed-toggles', voiceOk: 'ed-voiceOk',\n  modalBg: 'ed-modalBg', modalSm: 'ed-modalSm', lpTitle: 'ed-lpTitle', lpDraft: 'ed-lpDraft',\n  topbar: 'ed-topbar', prompt: 'ed-prompt', cursor: 'ed-cursor', spacer: 'ed-spacer',\n  editor: 'ed-editor', voiceQ: 'ed-voiceQ', seoRow: 'ed-seoRow', seo_ok: 'ed-seo_ok',\n  output: 'ed-output', lpList: 'ed-lpList', lpItem: 'ed-lpItem', lpTags: 'ed-lpTags',\n  saved: 'ed-saved', field: 'ed-field', input: 'ed-input', sideH: 'ed-sideH', modal: 'ed-modal',\n  muted: 'ed-muted', lpUrl: 'ed-lpUrl', lpSec: 'ed-lpSec', root: 'ed-root', wrap: 'ed-wrap',\n  tbOn: 'ed-tbOn', row2: 'ed-row2', tagX: 'ed-tagX', warn: 'ed-warn', btn: 'ed-btn', sep: 'ed-sep',\n  req: 'ed-req', tag: 'ed-tag', err: 'ed-err', tb: 'ed-tb', ok: 'ed-ok',\n};\n\nexport interface ArticuloRef {\n  id: string;\n  titulo: string;\n  seccion: string;\n  etiquetas: string[];\n  borrador: boolean;\n  url: string;\n  cuerpo?: string;\n  meta?: Partial<Meta>;\n}\nexport interface SeccionRef {\n  id: string;\n  nombre: string;\n  descriptor: string;\n}\ninterface Props {\n  articulos: ArticuloRef[];\n  secciones: SeccionRef[];\n}\n\nconst BORRADOR_KEY = 'editor:borrador:v1';\n\nexport default function Editor({ articulos, secciones }: Props) {\n  const [meta, setMeta] = useState<Meta>(() => ({\n    titulo: '',\n    descripcion: '',\n    seccion: secciones[0]?.id ?? '',\n    fecha: new Date().toISOString().slice(0, 10),\n    autor: NOMBRE_MEDIO,\n    fuente: '',\n    borrador: true,\n    etiquetas: [],\n    imagen: '',\n    imagenCredito: '',\n  }));\n  const [tagInput, setTagInput] = useState('');\n  const [mdx, setMdx] = useState('');\n  const [vistaMdx, setVistaMdx] = useState(true);\n  const [guardado, setGuardado] = useState<string>('');\n  const [linkPicker, setLinkPicker] = useState(false);\n  const [linkQuery, setLinkQuery] = useState('');\n  const [pexelsOpen, setPexelsOpen] = useState(false);\n  const [pexelsQuery, setPexelsQuery] = useState('');\n  const [pexelsFotos, setPexelsFotos] = useState<FotoPexels[]>([]);\n  const [pexelsCargando, setPexelsCargando] = useState(false);\n  const [pexelsError, setPexelsError] = useState('');\n  const [pexelsClave, setPexelsClave] = useState('');\n  const [abrirOpen, setAbrirOpen] = useState(false);\n  const [abrirQuery, setAbrirQuery] = useState('');\n  const [editandoId, setEditandoId] = useState<string | null>(null);\n  const tituloTouched = useRef(false);\n\n  const editor = useEditor({\n    immediatelyRender: false,\n    shouldRerenderOnTransaction: true,\n    extensions: [\n      StarterKit.configure({\n        heading: { levels: [1, 2, 3] },\n        link: { openOnClick: false, HTMLAttributes: { rel: 'noopener' } },\n      }),\n      Image.configure({ inline: false, allowBase64: true }),\n      Table.configure({ resizable: true }),\n      TableRow,\n      TableHeader,\n      TableCell,\n      Callout,\n      ElDato,\n      Cita,\n      Placeholder.configure({\n        placeholder: 'Escribe el artículo… El primer H1 es el título. Usa la barra para dar formato, insertar imágenes con pie, tablas y tus bloques propios (callout, dato, cita).',\n      }),\n    ],\n    content: '',\n    onUpdate: ({ editor }) => regenerar(editor.getJSON()),\n  });\n\n  const regenerar = useCallback((json: any) => {\n    const cuerpo = tiptapToMdx(json);\n    const h1 = json?.content?.find((n: any) => n.type === 'heading' && n.attrs?.level === 1);\n    const h1Text = h1 ? (h1.content ?? []).map((t: any) => t.text ?? '').join('') : '';\n    setMeta((m) => {\n      const nuevoTitulo = !tituloTouched.current && h1Text ? h1Text : m.titulo;\n      const full = buildFrontmatter({ ...m, titulo: nuevoTitulo }, NOMBRE_MEDIO) + '\\n' + cuerpo + '\\n';\n      setMdx(full);\n      return nuevoTitulo !== m.titulo ? { ...m, titulo: nuevoTitulo } : m;\n    });\n  }, []);\n\n  useEffect(() => {\n    if (!editor) return;\n    const cuerpo = tiptapToMdx(editor.getJSON());\n    setMdx(buildFrontmatter(meta, NOMBRE_MEDIO) + '\\n' + cuerpo + '\\n');\n  }, [meta, editor]);\n\n  useEffect(() => {\n    if (!editor) return;\n    const t = setTimeout(() => {\n      try {\n        localStorage.setItem(BORRADOR_KEY, JSON.stringify({ meta, doc: editor.getJSON(), ts: Date.now() }));\n        setGuardado(new Date().toLocaleTimeString('es-ES'));\n      } catch {}\n    }, 2000);\n    return () => clearTimeout(t);\n  }, [mdx, meta, editor]);\n\n  useEffect(() => {\n    if (!editor) return;\n    try {\n      const raw = localStorage.getItem(BORRADOR_KEY);\n      if (raw) {\n        const saved = JSON.parse(raw);\n        if (saved.doc && confirm('Hay un borrador guardado. ¿Restaurarlo?')) {\n          editor.commands.setContent(saved.doc);\n          if (saved.meta) {\n            tituloTouched.current = true;\n            setMeta(saved.meta);\n          }\n        }\n      }\n    } catch {}\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [editor]);\n\n  const texto = editor?.getText() ?? '';\n  const avisosVoz = useMemo(() => chequeoVoz(texto), [texto]);\n  const cuerpoActual = editor ? tiptapToMdx(editor.getJSON()) : '';\n  const seo = useMemo(() => {\n    const json = editor?.getJSON();\n    const links = contarEnlaces(json);\n    const imgs = contarImagenes(json);\n    return metricasSeo({\n      titulo: meta.titulo,\n      descripcion: meta.descripcion,\n      cuerpo: texto,\n      etiquetas: meta.etiquetas,\n      enlacesInternos: links.internos,\n      enlacesExternos: links.externos,\n      imagenesSinAlt: imgs.sinAlt,\n      imagenesTotal: imgs.total,\n      imagenSocial: meta.imagen,\n    });\n  }, [texto, meta, editor]);\n\n  const avisos = validarMeta(meta, cuerpoActual === '');\n\n  function onInsertarImagen() {\n    if (!editor) return;\n    const nombre = prompt(\n      'Nombre del archivo que has guardado en src/assets/\\n(ej: portada.webp). Recomendado: .webp o .avif ya optimizados.'\n    )?.trim();\n    if (!nombre) return;\n    let ruta = nombre;\n    if (!ruta.startsWith('/src/assets/')) {\n      ruta = '/src/assets/' + ruta.replace(/^\\/+/, '').replace(/^src\\/assets\\//, '');\n    }\n    const alt = prompt('Texto alternativo (alt) — describe la imagen para SEO y accesibilidad:')?.trim() ?? '';\n    if (!alt) {\n      if (!confirm('Sin alt la imagen penaliza SEO y accesibilidad. ¿Insertar igualmente?')) return;\n    }\n    const pie = prompt('Pie de foto (opcional) — se muestra bajo la imagen:')?.trim() ?? '';\n    editor.chain().focus().setImage({ src: ruta, alt, title: pie || undefined }).run();\n  }\n\n  function onInsertarCallout(tipo: 'lectura' | 'contexto') {\n    if (!editor) return;\n    (editor.chain().focus() as any).setCallout(tipo).run();\n  }\n\n  function onInsertarElDato() {\n    if (!editor) return;\n    const cifra = prompt('Cifra (ej: 32):')?.trim();\n    if (!cifra) return;\n    const unidad = prompt('Unidad (ej: %, goles, M€):')?.trim() ?? '';\n    const fuente = prompt('Fuente del dato:')?.trim() ?? '';\n    (editor.chain().focus() as any).insertElDato({ cifra, unidad, fuente }).run();\n  }\n\n  function onInsertarCita() {\n    if (!editor) return;\n    const autor = prompt('Autor de la cita:')?.trim();\n    if (!autor) return;\n    const cargo = prompt('Cargo (opcional):')?.trim() ?? '';\n    (editor.chain().focus() as any).insertCita({ autor, cargo }).run();\n  }\n\n  function onAbrirPexels() {\n    setPexelsClave(getClave());\n    const sugerencia = meta.etiquetas[0] || '';\n    setPexelsQuery(sugerencia);\n    setPexelsError('');\n    setPexelsFotos([]);\n    setPexelsOpen(true);\n    if (sugerencia && getClave()) void hacerBusqueda(sugerencia);\n  }\n\n  async function hacerBusqueda(q: string) {\n    if (!q.trim()) return;\n    setPexelsCargando(true);\n    setPexelsError('');\n    const r = await buscarFotos(q);\n    setPexelsCargando(false);\n    if (!r.ok) {\n      setPexelsError(r.error ?? 'Error desconocido');\n      setPexelsFotos([]);\n    } else {\n      setPexelsFotos(r.fotos);\n      if (r.fotos.length === 0) setPexelsError('Sin resultados para esa búsqueda.');\n    }\n  }\n\n  function elegirFotoPexels(f: FotoPexels) {\n    setMeta({ ...meta, imagen: f.src.landscape, imagenCredito: creditoTexto(f) });\n    setPexelsOpen(false);\n  }\n\n  function onImagenSocialLocal() {\n    const nombre = prompt('Nombre del archivo de imagen social en src/assets/\\n(ej: og-portada.webp). Recomendado 1200×630.')?.trim();\n    if (!nombre) return;\n    let ruta = nombre;\n    if (!ruta.startsWith('/src/assets/')) {\n      ruta = '/src/assets/' + ruta.replace(/^\\/+/, '').replace(/^src\\/assets\\//, '');\n    }\n    setMeta({ ...meta, imagen: ruta, imagenCredito: '' });\n  }\n\n  function abrirArticulo(a: ArticuloRef) {\n    if (!editor) return;\n    const hayTrabajo = editor.getText().trim().length > 0;\n    if (hayTrabajo && !confirm('Se perderá lo que hay ahora en el editor. ¿Abrir el artículo?')) return;\n    const doc = mdxToTiptap(a.cuerpo ?? '');\n    editor.commands.setContent(doc as any);\n    if (a.meta) {\n      tituloTouched.current = true;\n      setMeta((m) => ({ ...m, ...(a.meta as Meta) }));\n    }\n    setEditandoId(a.id);\n    setAbrirOpen(false);\n    setAbrirQuery('');\n  }\n\n  function nuevoArticulo() {\n    if (!editor) return;\n    if (editor.getText().trim() && !confirm('Se perderá lo que hay ahora. ¿Empezar de cero?')) return;\n    editor.commands.clearContent();\n    tituloTouched.current = false;\n    setEditandoId(null);\n    setMeta({\n      titulo: '', descripcion: '', seccion: secciones[0]?.id ?? '',\n      fecha: new Date().toISOString().slice(0, 10), autor: NOMBRE_MEDIO, fuente: '',\n      borrador: true, etiquetas: [], imagen: '', imagenCredito: '',\n    });\n  }\n\n  const articulosFiltrados = useMemo(() => {\n    const q = linkQuery.toLowerCase().trim();\n    return articulos\n      .filter((a) => (!q ? true : (a.titulo + ' ' + a.seccion + ' ' + a.etiquetas.join(' ')).toLowerCase().includes(q)))\n      .slice(0, 40);\n  }, [linkQuery, articulos]);\n\n  function insertarEnlaceInterno(a: ArticuloRef) {\n    if (!editor) return;\n    if (a.borrador && !confirm('Es un borrador: no tendrá URL pública en producción y el enlace quedaría roto. ¿Enlazar igual?')) return;\n    const { from, to } = editor.state.selection;\n    if (from === to) {\n      editor.chain().focus().insertContent('<a href=\"' + a.url + '\">' + a.titulo + '</a>').run();\n    } else {\n      editor.chain().focus().setLink({ href: a.url }).run();\n    }\n    setLinkPicker(false);\n    setLinkQuery('');\n  }\n\n  const [showOut, setShowOut] = useState(false);\n  const fname = (slugify(meta.titulo) || 'articulo') + '.mdx';\n  function copiar() {\n    navigator.clipboard.writeText(mdx);\n  }\n  function descargar() {\n    const blob = new Blob([mdx], { type: 'text/markdown' });\n    const a = document.createElement('a');\n    a.href = URL.createObjectURL(blob);\n    a.download = fname;\n    a.click();\n    URL.revokeObjectURL(a.href);\n  }\n  function limpiarBorrador() {\n    if (confirm('¿Borrar el borrador guardado y empezar de cero?')) {\n      localStorage.removeItem(BORRADOR_KEY);\n      editor?.commands.clearContent();\n      tituloTouched.current = false;\n      setMeta((m) => ({ ...m, titulo: '', descripcion: '', etiquetas: [], imagen: '' }));\n    }\n  }\n\n  const btn = (active: boolean) => styles.tb + ' ' + (active ? styles.tbOn : '');\n\n  return (\n    <div className={styles.root}>\n      <div className={styles.topbar}>\n        <span className={styles.prompt}>{NOMBRE_MEDIO} · editor<span className={styles.cursor} /></span>\n        <span className={styles.spacer} />\n        {editandoId && <span className={styles.saved}>editando: {editandoId}</span>}\n        {guardado && <span className={styles.saved}>guardado {guardado}</span>}\n        <button className={styles.btn} onClick={nuevoArticulo}>+ Nuevo</button>\n        <button className={styles.btn} onClick={() => setAbrirOpen(true)}>Abrir</button>\n        <button className={styles.btn} onClick={() => setVistaMdx((v) => !v)}>{vistaMdx ? 'Ocultar MDX' : 'Ver MDX'}</button>\n        <button className={styles.btn + ' ' + styles.primary} onClick={() => setShowOut(true)}>Generar .mdx</button>\n      </div>\n\n      <div className={styles.wrap}>\n        <div className={styles.colMain}>\n          {editor && (\n            <div className={styles.toolbar}>\n              <button className={btn(editor.isActive('heading', { level: 1 }))} title=\"Título (H1)\" onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()}>H1</button>\n              <button className={btn(editor.isActive('heading', { level: 2 }))} title=\"H2\" onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}>H2</button>\n              <button className={btn(editor.isActive('heading', { level: 3 }))} title=\"H3\" onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}>H3</button>\n              <span className={styles.sep} />\n              <button className={btn(editor.isActive('bold'))} title=\"Negrita\" onClick={() => editor.chain().focus().toggleBold().run()}>B</button>\n              <button className={btn(editor.isActive('italic'))} title=\"Cursiva\" onClick={() => editor.chain().focus().toggleItalic().run()}>I</button>\n              <button className={btn(editor.isActive('strike'))} title=\"Tachado\" onClick={() => editor.chain().focus().toggleStrike().run()}>S</button>\n              <button className={btn(editor.isActive('code'))} title=\"Código en línea\" onClick={() => editor.chain().focus().toggleCode().run()}>&lt;/&gt;</button>\n              <span className={styles.sep} />\n              <button className={styles.tb} title=\"Enlace interno a otro artículo\" onClick={() => setLinkPicker(true)}>enlace interno</button>\n              <button className={styles.tb} title=\"Enlace externo\" onClick={() => { const url = prompt('URL externa:', 'https://'); if (url) editor.chain().focus().setLink({ href: url }).run(); }}>enlace externo</button>\n              <span className={styles.sep} />\n              <button className={btn(editor.isActive('bulletList'))} title=\"Lista\" onClick={() => editor.chain().focus().toggleBulletList().run()}>lista</button>\n              <button className={btn(editor.isActive('orderedList'))} title=\"Lista numerada\" onClick={() => editor.chain().focus().toggleOrderedList().run()}>1. lista</button>\n              <button className={btn(editor.isActive('blockquote'))} title=\"Cita en bloque\" onClick={() => editor.chain().focus().toggleBlockquote().run()}>&gt; cita</button>\n              <button className={btn(editor.isActive('codeBlock'))} title=\"Bloque de código\" onClick={() => editor.chain().focus().toggleCodeBlock().run()}>código</button>\n              <button className={styles.tb} title=\"Separador\" onClick={() => editor.chain().focus().setHorizontalRule().run()}>—</button>\n              <span className={styles.sep} />\n              <button className={styles.tb} title=\"Insertar imagen desde src/assets/\" onClick={onInsertarImagen}>imagen</button>\n              <button className={styles.tb} title=\"Insertar tabla 2×2\" onClick={() => editor.chain().focus().insertTable({ rows: 2, cols: 2, withHeaderRow: true }).run()}>tabla</button>\n              {editor.isActive('table') && (\n                <>\n                  <button className={styles.tb} title=\"Añadir columna\" onClick={() => editor.chain().focus().addColumnAfter().run()}>+col</button>\n                  <button className={styles.tb} title=\"Quitar columna\" onClick={() => editor.chain().focus().deleteColumn().run()}>-col</button>\n                  <button className={styles.tb} title=\"Añadir fila\" onClick={() => editor.chain().focus().addRowAfter().run()}>+fila</button>\n                  <button className={styles.tb} title=\"Quitar fila\" onClick={() => editor.chain().focus().deleteRow().run()}>-fila</button>\n                  <button className={styles.tb} title=\"Borrar tabla\" onClick={() => editor.chain().focus().deleteTable().run()}>borrar tabla</button>\n                </>\n              )}\n              <span className={styles.sep} />\n              <button className={styles.tb} title=\"Callout: contexto\" onClick={() => onInsertarCallout('contexto')}>callout contexto</button>\n              <button className={styles.tb} title=\"Callout: lectura/opinión\" onClick={() => onInsertarCallout('lectura')}>callout lectura</button>\n              <button className={styles.tb} title=\"El Dato: cifra destacada\" onClick={onInsertarElDato}>el dato</button>\n              <button className={styles.tb} title=\"Cita atribuida\" onClick={onInsertarCita}>cita atribuida</button>\n              <span className={styles.sep} />\n              <button className={styles.tb} title=\"Deshacer\" onClick={() => editor.chain().focus().undo().run()}>deshacer</button>\n              <button className={styles.tb} title=\"Rehacer\" onClick={() => editor.chain().focus().redo().run()}>rehacer</button>\n            </div>\n          )}\n\n          <div className={styles.editorArea}>\n            <EditorContent editor={editor} className={styles.editor} />\n          </div>\n        </div>\n\n        <div className={styles.colSide}>\n          {vistaMdx ? (\n            <>\n              <div className={styles.sideH}>Vista MDX en vivo</div>\n              <pre className={styles.mdxPreview}>{mdx}</pre>\n            </>\n          ) : null}\n\n          <div className={styles.sideH}>Frontmatter</div>\n          <Campo label=\"titulo\" req counter={meta.titulo.length + '/110'} counterBad={meta.titulo.length > 110}>\n            <input className={styles.input} value={meta.titulo} onChange={(e) => { tituloTouched.current = true; setMeta({ ...meta, titulo: e.target.value }); }} />\n          </Campo>\n          <Campo label=\"descripcion\" req counter={meta.descripcion.length + '/200'} counterBad={meta.descripcion.length > 200} counterOk={meta.descripcion.length >= 140 && meta.descripcion.length <= 160}>\n            <textarea className={styles.input} rows={3} value={meta.descripcion} onChange={(e) => setMeta({ ...meta, descripcion: e.target.value })} />\n          </Campo>\n          <div className={styles.row2}>\n            <Campo label=\"seccion\" req>\n              <select className={styles.input} value={meta.seccion} onChange={(e) => setMeta({ ...meta, seccion: e.target.value })}>\n                {secciones.map((s) => <option key={s.id} value={s.id}>{s.nombre} · {s.descriptor}</option>)}\n              </select>\n            </Campo>\n            <Campo label=\"fecha\" req>\n              <input className={styles.input} value={meta.fecha} onChange={(e) => setMeta({ ...meta, fecha: e.target.value })} />\n            </Campo>\n          </div>\n          <div className={styles.row2}>\n            <Campo label=\"autor\" req>\n              <input className={styles.input} value={meta.autor} onChange={(e) => setMeta({ ...meta, autor: e.target.value })} />\n            </Campo>\n            <Campo label=\"fuente\">\n              <input className={styles.input} value={meta.fuente ?? ''} onChange={(e) => setMeta({ ...meta, fuente: e.target.value })} placeholder=\"(opcional)\" />\n            </Campo>\n          </div>\n          <Campo label=\"imagen social (OG)\">\n            <div style={{ display: 'flex', gap: '6px' }}>\n              <input className={styles.input} value={meta.imagen ?? ''} onChange={(e) => setMeta({ ...meta, imagen: e.target.value })} placeholder=\"URL o /src/assets/og.webp\" />\n              <button className={styles.btn} type=\"button\" title=\"Buscar en Pexels\" onClick={onAbrirPexels}>Pexels</button>\n              <button className={styles.btn} type=\"button\" title=\"Usar archivo de src/assets/\" onClick={onImagenSocialLocal}>archivo</button>\n            </div>\n            {meta.imagen && (\n              <div style={{ marginTop: '6px' }}>\n                <img src={meta.imagen} alt=\"\" style={{ width: '100%', borderRadius: '6px', border: '1px solid var(--regla)' }} />\n              </div>\n            )}\n            {meta.imagenCredito ? (\n              <input className={styles.input} value={meta.imagenCredito} onChange={(e) => setMeta({ ...meta, imagenCredito: e.target.value })} style={{ marginTop: '6px', fontSize: '12px' }} placeholder=\"Crédito\" />\n            ) : null}\n          </Campo>\n\n          <Campo label=\"etiquetas — Enter para añadir\">\n            <div className={styles.tagsBox}>\n              {meta.etiquetas.map((t, i) => (\n                <span key={i} className={styles.tag}>{t}\n                  <span className={styles.tagX} onClick={() => setMeta({ ...meta, etiquetas: meta.etiquetas.filter((_, j) => j !== i) })}>×</span>\n                </span>\n              ))}\n              <input className={styles.tagInput} value={tagInput} onChange={(e) => setTagInput(e.target.value)}\n                onKeyDown={(e) => {\n                  if (e.key === 'Enter' || e.key === ',') {\n                    e.preventDefault();\n                    const v = tagInput.trim().replace(/,$/, '');\n                    if (v && !meta.etiquetas.includes(v)) setMeta({ ...meta, etiquetas: [...meta.etiquetas, v] });\n                    setTagInput('');\n                  } else if (e.key === 'Backspace' && !tagInput && meta.etiquetas.length) {\n                    setMeta({ ...meta, etiquetas: meta.etiquetas.slice(0, -1) });\n                  }\n                }} placeholder=\"etiqueta1, etiqueta2…\" />\n            </div>\n          </Campo>\n\n          <div className={styles.toggles}>\n            <label><input type=\"checkbox\" checked={meta.borrador} onChange={(e) => setMeta({ ...meta, borrador: e.target.checked })} /> borrador</label>\n          </div>\n\n          <div className={styles.sideH}>Chequeo de voz</div>\n          {avisosVoz.length === 0 ? (\n            <div className={styles.voiceOk}>Sin avisos. La voz se sostiene.</div>\n          ) : (\n            avisosVoz.map((v, i) => (\n              <div key={i} className={styles.voiceItem + ' ' + (v.hard ? styles.voiceHard : '')}>\n                <div className={styles.voiceQ}>{v.q} · \"{v.frag}\"</div>\n                <div className={styles.voiceWhy}>{v.why}</div>\n              </div>\n            ))\n          )}\n\n          <div className={styles.sideH}>SEO</div>\n          {seo.map((r, i) => (\n            <div key={i} className={styles.seoRow + ' ' + styles['seo_' + r.estado]}>{r.texto}</div>\n          ))}\n\n          <div className={styles.sideH}>Borrador</div>\n          <button className={styles.btnGhost} onClick={limpiarBorrador}>Descartar borrador local</button>\n        </div>\n      </div>\n\n      {linkPicker && (\n        <div className={styles.modalBg} onClick={(e) => { if (e.target === e.currentTarget) setLinkPicker(false); }}>\n          <div className={styles.modalSm}>\n            <div className={styles.modalHead}>\n              <span className={styles.prompt}>enlazar &gt; buscar artículo</span>\n              <span className={styles.spacer} />\n              <button className={styles.btn} onClick={() => setLinkPicker(false)}>Cerrar</button>\n            </div>\n            <div className={styles.modalBody}>\n              <input className={styles.input} autoFocus placeholder=\"Busca por título, sección o etiqueta…\" value={linkQuery} onChange={(e) => setLinkQuery(e.target.value)} />\n              <div className={styles.lpList}>\n                {articulosFiltrados.length === 0 ? (\n                  <div className={styles.muted}>Sin resultados.</div>\n                ) : articulosFiltrados.map((a) => (\n                  <div key={a.id} className={styles.lpItem} onClick={() => insertarEnlaceInterno(a)}>\n                    <div>\n                      <div className={styles.lpTitle}>{a.titulo}</div>\n                      <div className={styles.lpUrl}>{a.url}</div>\n                    </div>\n                    <div className={styles.lpTags}>\n                      <span className={styles.lpSec}>{a.seccion}</span>\n                      {a.borrador && <span className={styles.lpDraft}>borrador</span>}\n                    </div>\n                  </div>\n                ))}\n              </div>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {abrirOpen && (\n        <div className={styles.modalBg} onClick={(e) => { if (e.target === e.currentTarget) setAbrirOpen(false); }}>\n          <div className={styles.modalSm}>\n            <div className={styles.modalHead}>\n              <span className={styles.prompt}>abrir &gt; mis artículos</span>\n              <span className={styles.spacer} />\n              <button className={styles.btn} onClick={() => setAbrirOpen(false)}>Cerrar</button>\n            </div>\n            <div className={styles.modalBody}>\n              <input className={styles.input} autoFocus placeholder=\"Busca por título, sección o etiqueta…\" value={abrirQuery} onChange={(e) => setAbrirQuery(e.target.value)} />\n              <div className={styles.lpList}>\n                {articulos\n                  .filter((a) => {\n                    const q = abrirQuery.toLowerCase().trim();\n                    return !q ? true : (a.titulo + ' ' + a.seccion + ' ' + a.etiquetas.join(' ')).toLowerCase().includes(q);\n                  })\n                  .map((a) => (\n                    <div key={a.id} className={styles.lpItem} onClick={() => abrirArticulo(a)}>\n                      <div>\n                        <div className={styles.lpTitle}>{a.titulo}</div>\n                        <div className={styles.lpUrl}>{a.id}.mdx</div>\n                      </div>\n                      <div className={styles.lpTags}>\n                        <span className={styles.lpSec}>{a.seccion}</span>\n                        {a.borrador && <span className={styles.lpDraft}>borrador</span>}\n                      </div>\n                    </div>\n                  ))}\n              </div>\n              <div style={{ fontSize: '11px', color: 'var(--tinta-suave)', marginTop: '10px', lineHeight: 1.5 }}>\n                Al abrir, edita y genera el .mdx. Luego reemplaza el archivo en src/content/articulos/. El editor no guarda por ti.\n              </div>\n            </div>\n          </div>\n        </div>\n      )}\n\n      {pexelsOpen && (\n        <div className={styles.modalBg} onClick={(e) => { if (e.target === e.currentTarget) setPexelsOpen(false); }}>\n          <div className={styles.modal}>\n            <div className={styles.modalHead}>\n              <span className={styles.prompt}>imagen social &gt; buscar en Pexels</span>\n              <span className={styles.spacer} />\n              <button className={styles.btn} onClick={() => setPexelsOpen(false)}>Cerrar</button>\n            </div>\n            <div className={styles.modalBody}>\n              {!getClave() ? (\n                <div>\n                  <div style={{ fontSize: '13px', marginBottom: '8px', lineHeight: 1.5 }}>\n                    Necesitas una clave de API de Pexels (gratis). Consíguela en{' '}\n                    <a href=\"https://www.pexels.com/api/\" target=\"_blank\" rel=\"noopener\" style={{ color: 'var(--primario)' }}>pexels.com/api</a> y pégala aquí. Se guarda solo en este navegador.\n                  </div>\n                  <div style={{ display: 'flex', gap: '6px' }}>\n                    <input className={styles.input} value={pexelsClave} onChange={(e) => setPexelsClave(e.target.value)} placeholder=\"Pega aquí tu clave de Pexels\" />\n                    <button className={styles.btn + ' ' + styles.primary} onClick={() => { setClave(pexelsClave); setPexelsError(''); setPexelsQuery(pexelsQuery); }}>Guardar</button>\n                  </div>\n                </div>\n              ) : (\n                <>\n                  <div style={{ display: 'flex', gap: '6px', marginBottom: '10px' }}>\n                    <input className={styles.input} autoFocus value={pexelsQuery} onChange={(e) => setPexelsQuery(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter') void hacerBusqueda(pexelsQuery); }} placeholder=\"Busca en inglés: city, people, technology…\" />\n                    <button className={styles.btn + ' ' + styles.primary} onClick={() => void hacerBusqueda(pexelsQuery)}>Buscar</button>\n                  </div>\n                  {pexelsCargando && <div className={styles.muted}>Buscando…</div>}\n                  {pexelsError && <div className={styles.voiceItem}><div className={styles.voiceQ}>{pexelsError}</div></div>}\n                  <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '8px' }}>\n                    {pexelsFotos.map((f) => (\n                      <div key={f.id} style={{ cursor: 'pointer' }} onClick={() => elegirFotoPexels(f)}>\n                        <img src={f.src.tiny} alt={f.alt} style={{ width: '100%', height: '90px', objectFit: 'cover', borderRadius: '6px', border: '1px solid var(--regla)', background: f.colorMedio }} />\n                        <div style={{ fontFamily: 'var(--mono)', fontSize: '10px', color: 'var(--tinta-suave)', marginTop: '3px' }}>{f.fotografo}</div>\n                      </div>\n                    ))}\n                  </div>\n                  <div style={{ fontSize: '11px', color: 'var(--tinta-suave)', marginTop: '12px', lineHeight: 1.5 }}>\n                    Fotos proporcionadas por <a href=\"https://www.pexels.com\" target=\"_blank\" rel=\"noopener\" style={{ color: 'var(--primario)' }}>Pexels</a>. Al elegir una, el crédito del fotógrafo se añade automáticamente.\n                  </div>\n                </>\n              )}\n            </div>\n          </div>\n        </div>\n      )}\n\n      {showOut && (\n        <div className={styles.modalBg} onClick={(e) => { if (e.target === e.currentTarget) setShowOut(false); }}>\n          <div className={styles.modal}>\n            <div className={styles.modalHead}>\n              <span className={styles.prompt}>~/articulos/{fname}</span>\n              <span className={styles.spacer} />\n              <button className={styles.btn} onClick={copiar}>Copiar</button>\n              <button className={styles.btn} onClick={descargar}>Descargar</button>\n              <button className={styles.btn} onClick={() => setShowOut(false)}>Cerrar</button>\n            </div>\n            <div className={styles.validation}>\n              {avisos.filter((a) => a.grave).length === 0 ? (\n                <span className={styles.ok}>Frontmatter válido. Listo para src/content/articulos/</span>\n              ) : (\n                <span className={styles.err}>{avisos.filter((a) => a.grave).length} error(es): {avisos.filter((a) => a.grave).map((a) => a.msg).join(' · ')}</span>\n              )}\n              {avisos.filter((a) => !a.grave).length > 0 && (\n                <span className={styles.warn}> · Recomendaciones: {avisos.filter((a) => !a.grave).map((a) => a.msg).join(' · ')}</span>\n              )}\n            </div>\n            <pre className={styles.output}>{mdx}</pre>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction Campo({ label, req, counter, counterOk, counterBad, children }: any) {\n  return (\n    <div className={styles.field}>\n      <label>\n        {label} {req && <span className={styles.req}>*</span>}\n        {counter && <span className={styles.counter + ' ' + (counterBad ? styles.counterBad : counterOk ? styles.counterOk : styles.counterWarn)}>{counter}</span>}\n      </label>\n      {children}\n    </div>\n  );\n}\n\nfunction contarEnlaces(json: any): { internos: number; externos: number } {\n  let internos = 0, externos = 0;\n  const walk = (n: any) => {\n    if (n?.marks) for (const m of n.marks) {\n      if (m.type === 'link') {\n        const href = m.attrs?.href ?? '';\n        if (href.startsWith('/')) internos++;\n        else externos++;\n      }\n    }\n    (n?.content ?? []).forEach(walk);\n  };\n  walk(json);\n  return { internos, externos };\n}\nfunction contarImagenes(json: any): { total: number; sinAlt: number } {\n  let total = 0, sinAlt = 0;\n  const walk = (n: any) => {\n    if (n?.type === 'image') { total++; if (!n.attrs?.alt) sinAlt++; }\n    (n?.content ?? []).forEach(walk);\n  };\n  walk(json);\n  return { total, sinAlt };\n}\n" },
  { path: "src/components/Editor/editor.css", content: "/* Editor — CSS global, importado directo en el .tsx.\n   Usa los tokens de marca del sitio (--primario, --acento, --fondo, --panel,\n   --tinta, --regla) definidos en src/layouts/Base.astro. */\n.ed-root {\n  --ambar: #d29922;\n  --rojo: #f85149;\n  --azul: #58a6ff;\n  background: var(--fondo);\n  color: var(--tinta);\n  font-family: var(--ui);\n  min-height: 100vh;\n}\n\n.ed-topbar {\n  position: sticky; top: 0; z-index: 50;\n  display: flex; align-items: center; gap: 12px;\n  padding: 10px 18px;\n  background: var(--panel);\n  border-bottom: 1px solid var(--regla);\n}\n.ed-prompt { font-family: var(--mono); color: var(--primario); font-weight: 600; font-size: 15px; white-space: nowrap; }\n.ed-cursor { display: inline-block; width: 8px; height: 16px; background: var(--primario); margin-left: 2px; vertical-align: middle; animation: ed-blink 1.1s steps(1) infinite; }\n@keyframes ed-blink { 50% { opacity: 0; } }\n.ed-spacer { flex: 1; }\n.ed-saved { font-family: var(--mono); font-size: 11px; color: var(--tinta-suave); }\n\n.ed-btn {\n  font-family: var(--mono); font-size: 13px;\n  background: transparent; color: var(--tinta);\n  border: 1px solid var(--regla); border-radius: 6px;\n  padding: 7px 12px; cursor: pointer; transition: all .15s;\n  display: inline-flex; align-items: center; gap: 6px;\n}\n.ed-btn:hover { border-color: var(--primario); color: var(--primario); }\n.ed-primary { background: var(--primario); color: var(--fondo); border-color: var(--primario); font-weight: 600; }\n.ed-primary:hover { opacity: .9; color: var(--fondo); }\n.ed-btnGhost {\n  font-family: var(--mono); font-size: 12px; background: transparent;\n  color: var(--tinta-suave); border: 1px solid var(--regla); border-radius: 6px;\n  padding: 6px 10px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px;\n}\n.ed-btnGhost:hover { border-color: var(--rojo); color: var(--rojo); }\n\n.ed-wrap { display: grid; grid-template-columns: 1fr 400px; min-height: calc(100vh - 53px); }\n.ed-colMain { padding: 18px 22px 120px; min-width: 0; }\n.ed-colSide {\n  border-left: 1px solid var(--regla); background: var(--panel);\n  padding: 16px 16px 60px; overflow-y: auto; max-height: calc(100vh - 53px);\n  position: sticky; top: 53px;\n}\n\n.ed-toolbar {\n  position: sticky; top: 53px; z-index: 40;\n  display: flex; flex-wrap: wrap; gap: 3px; align-items: center;\n  background: var(--panel); border: 1px solid var(--regla);\n  border-radius: 8px; padding: 6px; margin-bottom: 14px;\n}\n.ed-tb {\n  font-family: var(--mono); font-size: 12px;\n  background: transparent; color: var(--tinta);\n  border: 1px solid transparent; border-radius: 5px;\n  padding: 5px 8px; cursor: pointer;\n  display: inline-flex; align-items: center; gap: 4px; transition: all .12s;\n}\n.ed-tb:hover { background: var(--fondo); border-color: var(--regla); }\n.ed-tbOn { color: var(--primario); border-color: var(--primario); }\n.ed-sep { width: 1px; align-self: stretch; background: var(--regla); margin: 2px 3px; }\n\n.ed-editorArea { background: var(--fondo); }\n.ed-editor .ProseMirror { min-height: 460px; outline: none; font-size: 16px; line-height: 1.75; color: var(--tinta); }\n.ed-editor .ProseMirror h1 { font-size: 1.9em; line-height: 1.2; margin: .4em 0 .5em; }\n.ed-editor .ProseMirror h2 { font-size: 1.45em; margin: 1.3em 0 .5em; border-bottom: 1px solid var(--regla); padding-bottom: .2em; }\n.ed-editor .ProseMirror h3 { font-size: 1.2em; margin: 1.1em 0 .4em; }\n.ed-editor .ProseMirror p { margin: 0 0 1em; }\n.ed-editor .ProseMirror a { color: var(--azul); }\n.ed-editor .ProseMirror ul, .ed-editor .ProseMirror ol { margin: 0 0 1em; padding-left: 1.5em; }\n.ed-editor .ProseMirror blockquote { border-left: 3px solid var(--primario); margin: 1em 0; padding: .2em 1em; color: var(--tinta-suave); }\n.ed-editor .ProseMirror code { font-family: var(--mono); font-size: .88em; background: var(--panel); border: 1px solid var(--regla); border-radius: 4px; padding: 1px 5px; }\n.ed-editor .ProseMirror pre { background: var(--panel); border: 1px solid var(--regla); border-radius: 8px; padding: 14px 16px; overflow-x: auto; margin: 1em 0; }\n.ed-editor .ProseMirror pre code { background: none; border: none; padding: 0; }\n.ed-editor .ProseMirror hr { border: none; border-top: 1px solid var(--regla); margin: 1.6em 0; }\n.ed-editor .ProseMirror img { max-width: 100%; border-radius: 8px; border: 1px solid var(--regla); }\n.ed-editor .ProseMirror table { border-collapse: collapse; width: 100%; margin: 1em 0; }\n.ed-editor .ProseMirror th, .ed-editor .ProseMirror td { border: 1px solid var(--regla); padding: 6px 10px; }\n.ed-editor .ProseMirror th { background: var(--panel); }\n.ed-editor .ProseMirror p.is-editor-empty:first-child::before {\n  content: attr(data-placeholder); color: var(--tinta-suave); float: left; height: 0; pointer-events: none;\n}\n\n.ed-mdxPreview {\n  font-family: var(--mono); font-size: 11.5px; line-height: 1.55;\n  color: var(--tinta); background: var(--fondo); border: 1px solid var(--regla);\n  border-radius: 8px; padding: 12px; white-space: pre-wrap; word-break: break-word;\n  max-height: 320px; overflow: auto; margin: 0 0 8px;\n}\n\n.ed-field { margin-bottom: 12px; }\n.ed-field label { display: block; font-family: var(--mono); font-size: 11px; text-transform: uppercase; letter-spacing: .5px; color: var(--tinta-suave); margin-bottom: 5px; }\n.ed-req { color: var(--primario); }\n.ed-input {\n  width: 100%; background: var(--fondo); border: 1px solid var(--regla);\n  border-radius: 6px; color: var(--tinta); font-family: var(--ui); font-size: 14px;\n  padding: 8px 10px; resize: vertical;\n}\n.ed-input:focus { outline: none; border-color: var(--primario); }\n.ed-counter { float: right; font-family: var(--mono); font-size: 11px; }\n.ed-counterOk { color: var(--primario); }\n.ed-counterWarn { color: var(--ambar); }\n.ed-counterBad { color: var(--rojo); }\n.ed-row2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }\n\n.ed-sideH { font-family: var(--mono); font-size: 12px; text-transform: uppercase; letter-spacing: .8px; color: var(--primario); border-bottom: 1px solid var(--regla); padding-bottom: 6px; margin: 20px 0 12px; }\n\n.ed-tagsBox { display: flex; flex-wrap: wrap; gap: 6px; background: var(--fondo); border: 1px solid var(--regla); border-radius: 6px; padding: 7px; min-height: 40px; }\n.ed-tag { font-family: var(--mono); font-size: 12px; background: var(--panel); border: 1px solid var(--regla); border-radius: 4px; padding: 2px 7px; display: flex; align-items: center; gap: 5px; }\n.ed-tagX { cursor: pointer; color: var(--tinta-suave); font-weight: 700; }\n.ed-tagX:hover { color: var(--rojo); }\n.ed-tagInput { flex: 1; min-width: 80px; background: transparent; border: none; color: var(--tinta); font-family: var(--mono); font-size: 13px; outline: none; }\n\n.ed-toggles { display: flex; flex-direction: column; gap: 8px; margin: 8px 0; }\n.ed-toggles label { display: flex; align-items: center; gap: 8px; font-size: 13px; color: var(--tinta); }\n.ed-toggles input { width: 16px; height: 16px; accent-color: var(--primario); }\n\n.ed-voiceOk { font-size: 12px; color: var(--primario); font-family: var(--mono); padding: 6px 0; }\n.ed-voiceItem { font-size: 12px; line-height: 1.4; border-left: 3px solid var(--ambar); padding: 6px 10px; margin-bottom: 8px; background: var(--fondo); border-radius: 0 5px 5px 0; }\n.ed-voiceHard { border-left-color: var(--rojo); }\n.ed-voiceQ { color: var(--ambar); font-family: var(--mono); font-weight: 600; }\n.ed-voiceHard .ed-voiceQ { color: var(--rojo); }\n.ed-voiceWhy { color: var(--tinta-suave); margin-top: 3px; }\n\n.ed-seoRow { font-family: var(--mono); font-size: 12px; margin-bottom: 3px; }\n.ed-seo_ok { color: var(--primario); }\n.ed-seo_warn { color: var(--ambar); }\n.ed-seo_muted { color: var(--tinta-suave); }\n\n.ed-modalBg { position: fixed; inset: 0; z-index: 100; background: rgba(0,0,0,.8); display: flex; align-items: center; justify-content: center; padding: 30px; }\n.ed-modal { background: var(--panel); border: 1px solid var(--regla); border-radius: 12px; width: 100%; max-width: 860px; max-height: 85vh; display: flex; flex-direction: column; }\n.ed-modalSm { background: var(--panel); border: 1px solid var(--regla); border-radius: 12px; width: 100%; max-width: 560px; max-height: 80vh; display: flex; flex-direction: column; }\n.ed-modalHead { display: flex; align-items: center; gap: 12px; padding: 14px 18px; border-bottom: 1px solid var(--regla); }\n.ed-modalBody { padding: 14px 16px; overflow: auto; }\n.ed-output { margin: 0; padding: 18px; font-family: var(--mono); font-size: 12.5px; line-height: 1.6; color: var(--tinta); white-space: pre-wrap; word-break: break-word; overflow: auto; }\n.ed-validation { padding: 10px 18px; border-top: 1px solid var(--regla); font-family: var(--mono); font-size: 12px; }\n.ed-err { color: var(--rojo); }\n.ed-ok { color: var(--primario); }\n.ed-warn { color: var(--ambar); }\n.ed-muted { color: var(--tinta-suave); font-family: var(--mono); font-size: 12px; padding: 12px; }\n\n.ed-lpList { margin-top: 8px; max-height: 360px; overflow: auto; }\n.ed-lpItem { display: flex; justify-content: space-between; align-items: center; gap: 10px; padding: 9px 11px; border: 1px solid var(--regla); border-radius: 6px; margin-bottom: 6px; cursor: pointer; }\n.ed-lpItem:hover { border-color: var(--primario); }\n.ed-lpTitle { font-size: 13px; }\n.ed-lpUrl { font-family: var(--mono); font-size: 11px; color: var(--tinta-suave); }\n.ed-lpTags { display: flex; gap: 6px; flex-shrink: 0; }\n.ed-lpSec { font-family: var(--mono); font-size: 10px; color: var(--primario); border: 1px solid var(--regla); border-radius: 4px; padding: 1px 6px; }\n.ed-lpDraft { font-family: var(--mono); font-size: 10px; color: var(--ambar); border: 1px solid var(--ambar); border-radius: 4px; padding: 1px 6px; }\n\n@media (max-width: 960px) {\n  .ed-wrap { grid-template-columns: 1fr; }\n  .ed-colSide { position: static; max-height: none; border-left: none; border-top: 1px solid var(--regla); }\n}\n\n/* ===== Nodos propios dentro del editor (Callout, ElDato, Cita) ===== */\n.ed-editor .ProseMirror .ed-callout {\n  border: 1px solid var(--regla); border-left-width: 3px; border-radius: 0 8px 8px 0;\n  background: var(--panel); padding: 10px 14px; margin: 1em 0;\n}\n.ed-editor .ProseMirror .ed-callout[data-tipo=\"contexto\"] { border-left-color: var(--primario); }\n.ed-editor .ProseMirror .ed-callout[data-tipo=\"lectura\"] { border-left-color: var(--azul); }\n.ed-editor .ProseMirror .ed-callout::before {\n  content: attr(data-tipo); display: block; font-family: var(--mono); font-size: 10px;\n  text-transform: uppercase; letter-spacing: .08em; color: var(--tinta-suave); margin-bottom: 6px;\n}\n\n.ed-editor .ProseMirror .ed-eldato {\n  border: 1px solid var(--regla); border-radius: 8px; background: var(--panel); padding: 12px 14px; margin: 1em 0;\n}\n.ed-editor .ProseMirror .ed-eldato-cifra {\n  font-family: var(--ui); font-size: 1.6em; font-weight: 800; color: var(--primario); margin-bottom: 6px;\n}\n\n.ed-editor .ProseMirror .ed-cita {\n  border-left: 3px solid var(--azul); background: var(--panel); border-radius: 0 8px 8px 0;\n  padding: 10px 14px; margin: 1em 0; font-style: italic;\n}\n" },
  { path: "src/components/Dashboard/cardHelpers.ts", content: "/**\n * cardHelpers.ts — utilidades compartidas de las cards para redes sociales.\n *\n * Lee la paleta de marca en vivo desde las custom properties de CSS que\n * define src/layouts/Base.astro (--primario, --acento, --fondo, --panel,\n * --tinta), así que las cards salen siempre a juego con el logo del medio.\n */\nimport { useState, useEffect } from 'react';\n\nexport const HUMO = '#9aa3b0';\n\nexport interface Paleta {\n  primario: string;\n  acento: string;\n  fondo: string;\n  panel: string;\n  tinta: string;\n}\n\nconst PALETA_FALLBACK: Paleta = {\n  primario: '#6c5ce7', acento: '#a888f8', fondo: '#0b0e14', panel: '#141925', tinta: '#f0f2f5',\n};\n\nexport function usePaleta(): Paleta {\n  const [p, setP] = useState<Paleta>(PALETA_FALLBACK);\n  useEffect(() => {\n    const cs = getComputedStyle(document.documentElement);\n    const leer = (v: string, fallback: string) => {\n      const val = cs.getPropertyValue(v).trim();\n      return val || fallback;\n    };\n    setP({\n      primario: leer('--primario', PALETA_FALLBACK.primario),\n      acento: leer('--acento', PALETA_FALLBACK.acento),\n      fondo: leer('--fondo', PALETA_FALLBACK.fondo),\n      panel: leer('--panel', PALETA_FALLBACK.panel),\n      tinta: leer('--tinta', PALETA_FALLBACK.tinta),\n    });\n  }, []);\n  return p;\n}\n\nexport const LADO = 1080;\nexport const ALTO = 1350;\n\nexport type FormatoId = 'feed' | 'short' | 'og' | 'cuadrado';\n\nexport interface Formato {\n  id: FormatoId;\n  nombre: string;\n  destino: string;\n  w: number;\n  h: number;\n}\n\nexport const FORMATOS: Formato[] = [\n  { id: 'feed', nombre: 'Publicación', destino: 'Instagram · feed 4:5', w: 1080, h: 1350 },\n  { id: 'short', nombre: 'Short/Reel', destino: 'YouTube · TikTok 9:16', w: 1080, h: 1920 },\n  { id: 'og', nombre: 'Portada OG', destino: 'enlace compartido 1.91:1', w: 1200, h: 630 },\n  { id: 'cuadrado', nombre: 'Cuadrado', destino: 'X/Twitter 1:1', w: 1080, h: 1080 },\n];\n\nexport function useLogo(): HTMLImageElement | null {\n  const [logo, setLogo] = useState<HTMLImageElement | null>(null);\n  useEffect(() => {\n    const img = new Image();\n    img.onload = () => setLogo(img);\n    img.src = '/favicon.svg';\n  }, []);\n  return logo;\n}\n\nexport function redondeado(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {\n  ctx.beginPath();\n  ctx.moveTo(x + r, y);\n  ctx.arcTo(x + w, y, x + w, y + h, r);\n  ctx.arcTo(x + w, y + h, x, y + h, r);\n  ctx.arcTo(x, y + h, x, y, r);\n  ctx.arcTo(x, y, x + w, y, r);\n  ctx.closePath();\n}\n\nexport function envolver(ctx: CanvasRenderingContext2D, texto: string, maxW: number): string[] {\n  const palabras = texto.split(' ');\n  const lineas: string[] = [];\n  let actual = '';\n  for (const p of palabras) {\n    const prueba = actual ? actual + ' ' + p : p;\n    if (ctx.measureText(prueba).width > maxW && actual) {\n      lineas.push(actual);\n      actual = p;\n    } else {\n      actual = prueba;\n    }\n  }\n  if (actual) lineas.push(actual);\n  return lineas;\n}\n\nexport function pill(ctx: CanvasRenderingContext2D, texto: string, x: number, y: number, color: string, colorTexto: string, fontSize: number) {\n  const et = texto.toUpperCase();\n  ctx.font = '800 ' + fontSize + 'px system-ui';\n  const tw = ctx.measureText(et).width;\n  const padX = 22;\n  const pillH = fontSize + 20;\n  const pillW = tw + padX * 2;\n  const pillX = x - pillW;\n  ctx.fillStyle = color;\n  redondeado(ctx, pillX, y, pillW, pillH, pillH / 2);\n  ctx.fill();\n  ctx.fillStyle = colorTexto;\n  ctx.textAlign = 'center';\n  ctx.fillText(et, pillX + pillW / 2, y + pillH / 2 + fontSize * 0.35);\n  return pillW;\n}\n\nexport function descargarPNG(canvas: HTMLCanvasElement | null, nombre: string) {\n  if (!canvas) return;\n  const a = document.createElement('a');\n  a.download = nombre + '.png';\n  a.href = canvas.toDataURL('image/png');\n  a.click();\n}\n\nexport function estilos(esMovil: boolean) {\n  return {\n    label: { fontSize: '10px', fontWeight: 700, textTransform: 'uppercase' as const, letterSpacing: '.1em', color: HUMO, display: 'block', marginBottom: '5px' } as React.CSSProperties,\n    input: { width: '100%', background: 'var(--fondo)', border: '1px solid var(--regla)', borderRadius: '9px', color: 'var(--tinta)', fontFamily: 'system-ui', fontSize: esMovil ? '16px' : '13px', padding: '9px 11px', boxSizing: 'border-box' as const } as React.CSSProperties,\n    card: { background: 'var(--panel)', border: '1px solid var(--regla)', borderRadius: '14px', padding: '14px', boxShadow: '0 14px 32px -18px rgba(0,0,0,.65)' } as React.CSSProperties,\n    btnDescarga: { width: '100%', background: 'var(--primario)', border: 'none', borderRadius: '999px', color: 'var(--fondo)', fontFamily: 'system-ui', fontSize: '14px', fontWeight: 800, padding: '14px', cursor: 'pointer' } as React.CSSProperties,\n    formatoBtn: (activo: boolean) => ({\n      background: activo ? 'color-mix(in srgb, var(--primario) 15%, transparent)' : 'var(--fondo)',\n      border: '1px solid ' + (activo ? 'var(--primario)' : 'var(--regla)'),\n      borderRadius: '9px', color: activo ? 'var(--primario)' : HUMO, fontSize: '12px', fontWeight: 700,\n      padding: '10px 6px', cursor: 'pointer', textAlign: 'left' as const, lineHeight: 1.3,\n    } as React.CSSProperties),\n  };\n}\n" },
  { path: "src/components/Dashboard/cards/CardDato.tsx", content: "/**\n * CardDato.tsx — cifra grande, cuatro formatos. Foto de fondo opcional.\n */\nimport { useState, useRef, useEffect, useCallback } from 'react';\nimport { HUMO, FORMATOS, type FormatoId, useLogo, usePaleta, envolver, pill, descargarPNG, estilos } from '../cardHelpers';\n\nexport default function CardDato({ esMovil, nombreMedio }: { esMovil: boolean; nombreMedio: string }) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const logo = useLogo();\n  const paleta = usePaleta();\n  const [formato, setFormato] = useState<FormatoId>('feed');\n  const [foto, setFoto] = useState<HTMLImageElement | null>(null);\n  const [fotoY, setFotoY] = useState(0.5);\n  const [cifra, setCifra] = useState('32');\n  const [unidad, setUnidad] = useState('%');\n  const [contexto, setContexto] = useState('Contexto breve que explica por qué importa esta cifra.');\n  const [fuente, setFuente] = useState('');\n  const S = estilos(esMovil);\n  const fmt = FORMATOS.find((f) => f.id === formato)!;\n  const esHoriz = fmt.w > fmt.h;\n\n  const dibujar = useCallback(() => {\n    const ctx = canvasRef.current?.getContext('2d');\n    if (!ctx) return;\n    const W = fmt.w, H = fmt.h;\n    ctx.fillStyle = paleta.fondo; ctx.fillRect(0, 0, W, H);\n    if (foto) {\n      const e = Math.max(W / foto.width, H / foto.height), w = foto.width * e, h = foto.height * e;\n      ctx.save(); ctx.beginPath(); ctx.rect(0, 0, W, H); ctx.clip();\n      ctx.drawImage(foto, (W - w) / 2, (H - h) * fotoY, w, h); ctx.restore();\n      ctx.fillStyle = 'rgba(0,0,0,0.55)'; ctx.fillRect(0, 0, W, H);\n    } else {\n      ctx.fillStyle = paleta.panel; ctx.fillRect(0, 0, W, H);\n    }\n\n    const mx = Math.round(W * 0.065);\n    const protH = H * 0.14;\n    const gp = ctx.createLinearGradient(0, 0, 0, protH);\n    gp.addColorStop(0, 'rgba(0,0,0,0.55)'); gp.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = gp; ctx.fillRect(0, 0, W, protH);\n    if (logo) {\n      const lh = Math.round(H * 0.042), lw = logo.width * (lh / logo.height);\n      ctx.drawImage(logo, mx, mx * 0.7, lw, lh);\n      ctx.textAlign = 'left'; ctx.save(); ctx.shadowColor = 'rgba(0,0,0,0.55)'; ctx.shadowBlur = 8;\n      ctx.fillStyle = paleta.tinta; ctx.font = '900 ' + Math.round(lh * 0.5) + 'px system-ui';\n      ctx.fillText(nombreMedio, mx + lw + 16, mx * 0.7 + lh * 0.72);\n      ctx.restore();\n    }\n    const fsp = Math.round(H * 0.014) + 6;\n    pill(ctx, 'el dato', W - mx, mx * 0.7, paleta.primario, paleta.fondo, fsp);\n\n    const cx = W / 2, cy = esHoriz ? H * 0.5 : H * 0.44;\n    ctx.textAlign = 'center';\n    ctx.fillStyle = paleta.primario;\n    const cifraFs = esHoriz ? Math.round(H * 0.42) : Math.round(W * 0.34);\n    ctx.font = '900 ' + cifraFs + 'px Georgia, serif';\n    ctx.fillText(cifra, cx, cy);\n    ctx.fillStyle = paleta.tinta;\n    const uniFs = Math.round(cifraFs * 0.2);\n    ctx.font = '700 ' + uniFs + 'px Georgia, serif';\n    ctx.fillText(unidad, cx, cy + cifraFs * 0.28);\n    ctx.fillStyle = paleta.acento; ctx.fillRect(cx - 40, cy + cifraFs * 0.4, 80, 5);\n    ctx.fillStyle = HUMO;\n    const ctxFs = esHoriz ? Math.round(H * 0.045) : Math.round(W * 0.028);\n    ctx.font = '400 ' + ctxFs + 'px system-ui';\n    let yy = cy + cifraFs * 0.4 + ctxFs * 1.8;\n    for (const ln of envolver(ctx, contexto, W * 0.8)) { ctx.fillText(ln, cx, yy); yy += ctxFs * 1.4; }\n\n    if (fuente.trim()) {\n      ctx.fillStyle = HUMO; ctx.font = '400 18px system-ui'; ctx.textAlign = 'right';\n      ctx.fillText('Vía ' + fuente, W - mx, H - Math.round(H * 0.03));\n    }\n  }, [fmt, esHoriz, foto, fotoY, logo, paleta, nombreMedio, cifra, unidad, contexto, fuente]);\n\n  useEffect(() => { dibujar(); }, [dibujar]);\n  const subirFoto = (e: React.ChangeEvent<HTMLInputElement>) => {\n    const fl = e.target.files?.[0]; if (!fl) return;\n    const i = new Image(); i.onload = () => setFoto(i); i.src = URL.createObjectURL(fl);\n  };\n\n  return (\n    <div style={{ display: esMovil ? 'block' : 'grid', gridTemplateColumns: '1fr 340px', gap: '20px' }}>\n      <div><canvas ref={canvasRef} width={fmt.w} height={fmt.h} style={{ width: '100%', maxWidth: esHoriz ? '640px' : '440px', borderRadius: '10px', border: '1px solid var(--regla)', display: 'block', margin: '0 auto' }} /></div>\n      <div style={{ marginTop: esMovil ? '16px' : 0 }}>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Formato</label>\n          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px' }}>\n            {FORMATOS.map((f) => (\n              <button key={f.id} onClick={() => setFormato(f.id)} style={S.formatoBtn(formato === f.id)}>\n                {f.nombre}<br /><span style={{ fontSize: '9px', fontWeight: 400 }}>{f.destino}</span>\n              </button>\n            ))}\n          </div>\n        </div>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Foto de fondo (opcional)</label>\n          <input type=\"file\" accept=\"image/*\" onChange={subirFoto} style={{ ...S.input, padding: '8px' }} />\n          {foto && (\n            <div style={{ marginTop: '10px' }}>\n              <label style={S.label}>Encuadre vertical</label>\n              <input type=\"range\" min={0} max={1} step={0.01} value={fotoY} onChange={(e) => setFotoY(Number(e.target.value))} style={{ width: '100%' }} />\n            </div>\n          )}\n        </div>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <div style={{ display: 'flex', gap: '8px' }}>\n            <div style={{ flex: '0 0 40%' }}><label style={S.label}>Cifra</label><input style={{ ...S.input, fontSize: esMovil ? '20px' : '18px', fontWeight: 800, textAlign: 'center' }} value={cifra} onChange={(e) => setCifra(e.target.value)} /></div>\n            <div style={{ flex: 1 }}><label style={S.label}>Unidad</label><input style={S.input} value={unidad} onChange={(e) => setUnidad(e.target.value)} /></div>\n          </div>\n          <label style={{ ...S.label, marginTop: '10px' }}>Contexto</label>\n          <textarea style={{ ...S.input, minHeight: '90px', resize: 'vertical' }} value={contexto} onChange={(e) => setContexto(e.target.value)} />\n          <label style={{ ...S.label, marginTop: '10px' }}>Fuente</label>\n          <input style={S.input} value={fuente} onChange={(e) => setFuente(e.target.value)} />\n        </div>\n        <button onClick={() => descargarPNG(canvasRef.current, 'dato-' + formato + '-' + cifra)} style={S.btnDescarga}>Descargar {fmt.w}×{fmt.h}</button>\n      </div>\n    </div>\n  );\n}\n" },
  { path: "src/components/Dashboard/cards/CardCita.tsx", content: "/**\n * CardCita.tsx — la cita del día, cuatro formatos, sin foto.\n */\nimport { useState, useRef, useEffect, useCallback } from 'react';\nimport { HUMO, FORMATOS, type FormatoId, useLogo, usePaleta, envolver, pill, descargarPNG, estilos } from '../cardHelpers';\n\nexport default function CardCita({ esMovil, nombreMedio }: { esMovil: boolean; nombreMedio: string }) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const logo = useLogo();\n  const paleta = usePaleta();\n  const [formato, setFormato] = useState<FormatoId>('feed');\n  const [cita, setCita] = useState('Escribe aquí la cita que quieres destacar.');\n  const [autor, setAutor] = useState('Nombre del autor');\n  const [cargo, setCargo] = useState('Cargo o contexto');\n  const [fuente, setFuente] = useState('');\n  const S = estilos(esMovil);\n  const fmt = FORMATOS.find((f) => f.id === formato)!;\n  const esHoriz = fmt.w > fmt.h;\n\n  const dibujar = useCallback(() => {\n    const ctx = canvasRef.current?.getContext('2d');\n    if (!ctx) return;\n    const W = fmt.w, H = fmt.h;\n    ctx.fillStyle = paleta.panel; ctx.fillRect(0, 0, W, H);\n    ctx.fillStyle = paleta.fondo; ctx.fillRect(0, 0, W, H * 0.16); ctx.fillRect(0, H * 0.84, W, H * 0.16);\n\n    const mx = Math.round(W * 0.065);\n    if (logo) {\n      const lh = Math.round(H * 0.042), lw = logo.width * (lh / logo.height);\n      ctx.drawImage(logo, mx, mx * 0.7, lw, lh);\n      ctx.textAlign = 'left'; ctx.fillStyle = paleta.tinta; ctx.font = '900 ' + Math.round(lh * 0.5) + 'px system-ui';\n      ctx.fillText(nombreMedio, mx + lw + 16, mx * 0.7 + lh * 0.72);\n    }\n    const fsp = Math.round(H * 0.014) + 6;\n    pill(ctx, 'la cita', W - mx, mx * 0.7, paleta.acento, paleta.fondo, fsp);\n\n    const cx = W / 2;\n    ctx.textAlign = 'center';\n    const citaFs = esHoriz ? Math.round(H * 0.085) : Math.round(W * 0.052);\n    ctx.fillStyle = paleta.primario; ctx.font = '900 ' + Math.round(citaFs * 3) + 'px Georgia, serif';\n    const lineas = envolver(ctx, cita, W * 0.82);\n    const lineH = citaFs * 1.28;\n    const bloqueH = lineas.length * lineH;\n    const baseY = (H - bloqueH) / 2;\n    ctx.fillText('“', cx, baseY - citaFs * 0.6);\n    ctx.font = '700 ' + citaFs + 'px Georgia, serif';\n    let yy = baseY;\n    lineas.forEach((ln, i) => {\n      ctx.fillStyle = i === lineas.length - 1 ? paleta.primario : paleta.tinta;\n      ctx.fillText(ln, cx, yy);\n      yy += lineH;\n    });\n\n    const yA = yy + 40;\n    ctx.fillStyle = paleta.acento; ctx.fillRect(cx - 45, yA, 90, 5);\n    ctx.fillStyle = paleta.tinta; ctx.font = '900 ' + Math.round(citaFs * 0.62) + 'px system-ui';\n    ctx.fillText(autor.toUpperCase(), cx, yA + citaFs);\n    if (cargo.trim()) {\n      ctx.fillStyle = HUMO; ctx.font = '400 ' + Math.round(citaFs * 0.4) + 'px system-ui';\n      ctx.fillText(cargo, cx, yA + citaFs * 1.55);\n    }\n\n    if (fuente.trim()) {\n      ctx.fillStyle = HUMO; ctx.font = '400 18px system-ui'; ctx.textAlign = 'right';\n      ctx.fillText('Vía ' + fuente, W - mx, H - Math.round(H * 0.03));\n    }\n  }, [fmt, esHoriz, logo, paleta, nombreMedio, cita, autor, cargo, fuente]);\n\n  useEffect(() => { dibujar(); }, [dibujar]);\n\n  return (\n    <div style={{ display: esMovil ? 'block' : 'grid', gridTemplateColumns: '1fr 340px', gap: '20px' }}>\n      <div><canvas ref={canvasRef} width={fmt.w} height={fmt.h} style={{ width: '100%', maxWidth: esHoriz ? '640px' : '440px', borderRadius: '10px', border: '1px solid var(--regla)', display: 'block', margin: '0 auto' }} /></div>\n      <div style={{ marginTop: esMovil ? '16px' : 0 }}>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Formato</label>\n          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px' }}>\n            {FORMATOS.map((f) => (\n              <button key={f.id} onClick={() => setFormato(f.id)} style={S.formatoBtn(formato === f.id)}>\n                {f.nombre}<br /><span style={{ fontSize: '9px', fontWeight: 400 }}>{f.destino}</span>\n              </button>\n            ))}\n          </div>\n        </div>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Cita</label>\n          <textarea style={{ ...S.input, minHeight: '110px', resize: 'vertical' }} value={cita} onChange={(e) => setCita(e.target.value)} />\n          <label style={{ ...S.label, marginTop: '10px' }}>Autor</label>\n          <input style={S.input} value={autor} onChange={(e) => setAutor(e.target.value)} />\n          <label style={{ ...S.label, marginTop: '10px' }}>Cargo</label>\n          <input style={S.input} value={cargo} onChange={(e) => setCargo(e.target.value)} />\n          <label style={{ ...S.label, marginTop: '10px' }}>Fuente (opcional)</label>\n          <input style={S.input} value={fuente} onChange={(e) => setFuente(e.target.value)} />\n        </div>\n        <button onClick={() => descargarPNG(canvasRef.current, 'cita-' + formato + '-' + autor.toLowerCase().replace(/\\s+/g, '-'))} style={S.btnDescarga}>Descargar {fmt.w}×{fmt.h}</button>\n      </div>\n    </div>\n  );\n}\n" },
  { path: "src/components/Dashboard/cards/CardUltimaHora.tsx", content: "/**\n * CardUltimaHora.tsx — breaking news, cuatro formatos.\n */\nimport { useState, useRef, useEffect, useCallback } from 'react';\nimport { HUMO, FORMATOS, type FormatoId, useLogo, usePaleta, envolver, pill, descargarPNG, estilos } from '../cardHelpers';\n\nconst ROJO = '#e53e3e';\n\nexport default function CardUltimaHora({ esMovil, nombreMedio }: { esMovil: boolean; nombreMedio: string }) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const logo = useLogo();\n  const paleta = usePaleta();\n  const [formato, setFormato] = useState<FormatoId>('feed');\n  const [foto, setFoto] = useState<HTMLImageElement | null>(null);\n  const [fotoY, setFotoY] = useState(0.5);\n  const [titular, setTitular] = useState('Escribe aquí el titular de última hora');\n  const [bajada, setBajada] = useState('Una frase de contexto');\n  const [fuente, setFuente] = useState('');\n  const S = estilos(esMovil);\n  const fmt = FORMATOS.find((f) => f.id === formato)!;\n  const esHoriz = fmt.w > fmt.h;\n\n  const dibujar = useCallback(() => {\n    const ctx = canvasRef.current?.getContext('2d');\n    if (!ctx) return;\n    const W = fmt.w, H = fmt.h;\n    ctx.fillStyle = paleta.fondo; ctx.fillRect(0, 0, W, H);\n\n    if (foto) {\n      const escala = Math.max(W / foto.width, H / foto.height);\n      const w = foto.width * escala, h = foto.height * escala;\n      ctx.save(); ctx.beginPath(); ctx.rect(0, 0, W, H); ctx.clip();\n      ctx.drawImage(foto, (W - w) / 2, (H - h) * fotoY, w, h); ctx.restore();\n    } else {\n      ctx.fillStyle = paleta.panel; ctx.fillRect(0, 0, W, H);\n    }\n\n    if (esHoriz) {\n      const g = ctx.createLinearGradient(0, 0, W * 0.75, 0);\n      g.addColorStop(0, 'rgba(0,0,0,0.85)'); g.addColorStop(0.6, 'rgba(0,0,0,0.6)'); g.addColorStop(1, 'rgba(0,0,0,0)');\n      ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);\n    } else {\n      const g = ctx.createLinearGradient(0, H * 0.30, 0, H);\n      g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(0.5, 'rgba(0,0,0,0.8)'); g.addColorStop(1, 'rgba(0,0,0,0.92)');\n      ctx.fillStyle = g; ctx.fillRect(0, H * 0.30, W, H * 0.70);\n    }\n\n    const mx = Math.round(W * 0.065);\n    const protH = H * 0.14;\n    const gp = ctx.createLinearGradient(0, 0, 0, protH);\n    gp.addColorStop(0, 'rgba(0,0,0,0.8)'); gp.addColorStop(1, 'rgba(0,0,0,0)');\n    ctx.fillStyle = gp; ctx.fillRect(0, 0, W, protH);\n    if (logo) {\n      const lh = Math.round(H * 0.042), lw = logo.width * (lh / logo.height);\n      ctx.drawImage(logo, mx, mx * 0.7, lw, lh);\n      ctx.textAlign = 'left'; ctx.save(); ctx.shadowColor = 'rgba(0,0,0,0.55)'; ctx.shadowBlur = 8;\n      ctx.fillStyle = paleta.tinta; ctx.font = '900 ' + Math.round(lh * 0.5) + 'px system-ui';\n      ctx.fillText(nombreMedio, mx + lw + 16, mx * 0.7 + lh * 0.72);\n      ctx.restore();\n    }\n    const fs = Math.round(H * 0.014) + 6;\n    pill(ctx, 'última hora', W - mx, mx * 0.7, ROJO, '#ffffff', fs);\n\n    const anchoTexto = esHoriz ? W * 0.62 : W - mx * 2;\n    const titFs = esHoriz ? Math.round(H * 0.075) : Math.round(W * 0.056);\n    ctx.textAlign = 'left'; ctx.font = '900 ' + titFs + 'px system-ui';\n    const lineas = envolver(ctx, titular, anchoTexto);\n    const lineH = titFs * 1.16;\n    const bajFs = Math.round(titFs * 0.42);\n    const bajLineas = bajada.trim() ? envolver(ctx, bajada, anchoTexto) : [];\n\n    let baseY;\n    if (esHoriz) {\n      const bloqueH = lineas.length * lineH + bajLineas.length * bajFs * 1.3 + 80;\n      baseY = (H - bloqueH) / 2 + titFs;\n    } else {\n      baseY = H - (lineas.length * lineH) - (bajLineas.length * bajFs * 1.3) - 200;\n    }\n    ctx.fillStyle = ROJO; ctx.fillRect(mx, baseY - titFs - 30, 60, 5);\n    ctx.font = '800 ' + Math.round(titFs * 0.34) + 'px system-ui';\n    ctx.fillText('AHORA', mx, baseY - titFs - 8);\n\n    ctx.font = '900 ' + titFs + 'px system-ui'; ctx.fillStyle = paleta.tinta;\n    let yy = baseY;\n    for (const ln of lineas) { ctx.fillText(ln, mx, yy); yy += lineH; }\n    if (bajLineas.length) {\n      ctx.font = '400 ' + bajFs + 'px system-ui'; ctx.fillStyle = HUMO; yy += 8;\n      for (const ln of bajLineas) { ctx.fillText(ln, mx, yy); yy += bajFs * 1.3; }\n    }\n\n    if (fuente.trim()) {\n      ctx.fillStyle = HUMO; ctx.font = '400 18px system-ui'; ctx.textAlign = 'right';\n      ctx.fillText('Vía ' + fuente, W - mx, H - Math.round(H * 0.03));\n    }\n  }, [fmt, esHoriz, foto, fotoY, logo, paleta, nombreMedio, titular, bajada, fuente]);\n\n  useEffect(() => { dibujar(); }, [dibujar]);\n  const subirFoto = (e: React.ChangeEvent<HTMLInputElement>) => {\n    const f = e.target.files?.[0]; if (!f) return;\n    const i = new Image(); i.onload = () => setFoto(i); i.src = URL.createObjectURL(f);\n  };\n\n  return (\n    <div style={{ display: esMovil ? 'block' : 'grid', gridTemplateColumns: '1fr 340px', gap: '20px' }}>\n      <div><canvas ref={canvasRef} width={fmt.w} height={fmt.h} style={{ width: '100%', maxWidth: esHoriz ? '640px' : '440px', borderRadius: '10px', border: '1px solid var(--regla)', display: 'block', margin: '0 auto' }} /></div>\n      <div style={{ marginTop: esMovil ? '16px' : 0 }}>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Formato</label>\n          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px' }}>\n            {FORMATOS.map((f) => (\n              <button key={f.id} onClick={() => setFormato(f.id)} style={S.formatoBtn(formato === f.id)}>\n                {f.nombre}<br /><span style={{ fontSize: '9px', fontWeight: 400 }}>{f.destino}</span>\n              </button>\n            ))}\n          </div>\n        </div>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Foto</label>\n          <input type=\"file\" accept=\"image/*\" onChange={subirFoto} style={{ ...S.input, padding: '8px' }} />\n          {foto && (\n            <div style={{ marginTop: '10px' }}>\n              <label style={S.label}>Encuadre vertical</label>\n              <input type=\"range\" min={0} max={1} step={0.01} value={fotoY} onChange={(e) => setFotoY(Number(e.target.value))} style={{ width: '100%' }} />\n            </div>\n          )}\n        </div>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Titular</label>\n          <textarea style={{ ...S.input, minHeight: '80px', resize: 'vertical' }} value={titular} onChange={(e) => setTitular(e.target.value)} />\n          <label style={{ ...S.label, marginTop: '10px' }}>Bajada</label>\n          <input style={S.input} value={bajada} onChange={(e) => setBajada(e.target.value)} />\n          <label style={{ ...S.label, marginTop: '10px' }}>Fuente</label>\n          <input style={S.input} value={fuente} onChange={(e) => setFuente(e.target.value)} />\n        </div>\n        <button onClick={() => descargarPNG(canvasRef.current, 'ultimahora-' + formato + '-' + Date.now())} style={S.btnDescarga}>Descargar {fmt.w}×{fmt.h}</button>\n      </div>\n    </div>\n  );\n}\n" },
  { path: "src/components/Dashboard/cards/CardClaves.tsx", content: "/**\n * CardClaves.tsx — claves numeradas, cuatro formatos. Sin foto.\n */\nimport { useState, useRef, useEffect, useCallback } from 'react';\nimport { FORMATOS, type FormatoId, useLogo, usePaleta, envolver, pill, descargarPNG, estilos } from '../cardHelpers';\n\nexport default function CardClaves({ esMovil, nombreMedio }: { esMovil: boolean; nombreMedio: string }) {\n  const canvasRef = useRef<HTMLCanvasElement>(null);\n  const logo = useLogo();\n  const paleta = usePaleta();\n  const [formato, setFormato] = useState<FormatoId>('feed');\n  const [titulo, setTitulo] = useState('Las claves');\n  const [claves, setClaves] = useState('Primera clave\\nSegunda clave\\nTercera clave');\n  const S = estilos(esMovil);\n  const fmt = FORMATOS.find((f) => f.id === formato)!;\n  const esHoriz = fmt.w > fmt.h;\n\n  const dibujar = useCallback(() => {\n    const ctx = canvasRef.current?.getContext('2d');\n    if (!ctx) return;\n    const W = fmt.w, H = fmt.h;\n    ctx.fillStyle = paleta.panel; ctx.fillRect(0, 0, W, H);\n    ctx.fillStyle = paleta.fondo; ctx.fillRect(0, 0, W, H * 0.16);\n\n    const mx = Math.round(W * 0.065);\n    if (logo) {\n      const lh = Math.round(H * 0.042), lw = logo.width * (lh / logo.height);\n      ctx.drawImage(logo, mx, mx * 0.7, lw, lh);\n      ctx.textAlign = 'left'; ctx.fillStyle = paleta.tinta; ctx.font = '900 ' + Math.round(lh * 0.5) + 'px system-ui';\n      ctx.fillText(nombreMedio, mx + lw + 16, mx * 0.7 + lh * 0.72);\n    }\n    const fsp = Math.round(H * 0.014) + 6;\n    pill(ctx, 'las claves', W - mx, mx * 0.7, paleta.primario, paleta.fondo, fsp);\n\n    ctx.textAlign = 'left';\n    const titFs = esHoriz ? Math.round(H * 0.07) : Math.round(W * 0.05);\n    ctx.fillStyle = paleta.tinta; ctx.font = '900 ' + titFs + 'px system-ui';\n    let y = H * 0.24;\n    for (const ln of envolver(ctx, titulo, W - mx * 2)) { ctx.fillText(ln, mx, y); y += titFs * 1.15; }\n    ctx.fillStyle = paleta.acento; ctx.fillRect(mx, y - titFs * 0.4, 90, 6); y += titFs * 0.6;\n\n    const lista = claves.split('\\n').map((l) => l.trim()).filter(Boolean).slice(0, 5);\n    const numFs = esHoriz ? Math.round(H * 0.09) : Math.round(W * 0.052);\n    const txtFs = esHoriz ? Math.round(H * 0.05) : Math.round(W * 0.03);\n    const disponible = H * 0.9 - y;\n    const pasoMax = disponible / lista.length;\n    lista.forEach((c, i) => {\n      ctx.fillStyle = paleta.primario; ctx.font = '900 ' + numFs + 'px Georgia, serif';\n      ctx.fillText(String(i + 1), mx, y + txtFs);\n      ctx.fillStyle = paleta.tinta; ctx.font = '600 ' + txtFs + 'px system-ui';\n      const lns = envolver(ctx, c, W - mx - numFs * 2.2);\n      let yy = y + txtFs * 0.85;\n      for (const ln of lns) { ctx.fillText(ln, mx + numFs * 1.6, yy); yy += txtFs * 1.25; }\n      y += Math.max(yy - y + txtFs * 0.6, pasoMax * 0.7);\n    });\n  }, [fmt, esHoriz, logo, paleta, nombreMedio, titulo, claves]);\n\n  useEffect(() => { dibujar(); }, [dibujar]);\n\n  return (\n    <div style={{ display: esMovil ? 'block' : 'grid', gridTemplateColumns: '1fr 340px', gap: '20px' }}>\n      <div><canvas ref={canvasRef} width={fmt.w} height={fmt.h} style={{ width: '100%', maxWidth: esHoriz ? '640px' : '440px', borderRadius: '10px', border: '1px solid var(--regla)', display: 'block', margin: '0 auto' }} /></div>\n      <div style={{ marginTop: esMovil ? '16px' : 0 }}>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Formato</label>\n          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px' }}>\n            {FORMATOS.map((f) => (\n              <button key={f.id} onClick={() => setFormato(f.id)} style={S.formatoBtn(formato === f.id)}>\n                {f.nombre}<br /><span style={{ fontSize: '9px', fontWeight: 400 }}>{f.destino}</span>\n              </button>\n            ))}\n          </div>\n        </div>\n        <div style={{ ...S.card, marginBottom: '12px' }}>\n          <label style={S.label}>Título</label>\n          <input style={S.input} value={titulo} onChange={(e) => setTitulo(e.target.value)} />\n          <label style={{ ...S.label, marginTop: '10px' }}>Claves — una por línea (máx. 5)</label>\n          <textarea style={{ ...S.input, minHeight: '180px', resize: 'vertical', lineHeight: 1.5 }} value={claves} onChange={(e) => setClaves(e.target.value)} />\n        </div>\n        <button onClick={() => descargarPNG(canvasRef.current, 'claves-' + formato + '-' + Date.now())} style={S.btnDescarga}>Descargar {fmt.w}×{fmt.h}</button>\n      </div>\n    </div>\n  );\n}\n" },
  { path: "src/components/Dashboard/Dashboard.tsx", content: "/**\n * Dashboard — sala de redacción mínima: editor de artículos + creador de\n * cards para redes sociales. Generado por Fábrica de medios.\n */\nimport { useEffect, useState } from 'react';\nimport Editor, { type ArticuloRef, type SeccionRef } from '../Editor/Editor';\nimport CardDato from './cards/CardDato';\nimport CardCita from './cards/CardCita';\nimport CardUltimaHora from './cards/CardUltimaHora';\nimport CardClaves from './cards/CardClaves';\nimport { NOMBRE_MEDIO } from '../../lib/medio';\nimport './dashboard.css';\n\nfunction useMovil(breakpoint = 860): boolean {\n  const [esMovil, setEsMovil] = useState(false);\n  useEffect(() => {\n    const mq = window.matchMedia('(max-width: ' + breakpoint + 'px)');\n    const actualizar = () => setEsMovil(mq.matches);\n    actualizar();\n    mq.addEventListener('change', actualizar);\n    return () => mq.removeEventListener('change', actualizar);\n  }, [breakpoint]);\n  return esMovil;\n}\n\ntype Vista = 'editor' | 'cards';\ntype TipoCard = 'dato' | 'cita' | 'ultimahora' | 'claves';\n\ninterface Props {\n  articulos: ArticuloRef[];\n  secciones: SeccionRef[];\n}\n\nexport default function Dashboard({ articulos, secciones }: Props) {\n  const esMovil = useMovil();\n  const [vista, setVista] = useState<Vista>('editor');\n  const [tipoCard, setTipoCard] = useState<TipoCard>('dato');\n\n  return (\n    <div className=\"db-root\">\n      <div className=\"db-tabs\">\n        <button className={'db-tab' + (vista === 'editor' ? ' activo' : '')} onClick={() => setVista('editor')}>Editor</button>\n        <button className={'db-tab' + (vista === 'cards' ? ' activo' : '')} onClick={() => setVista('cards')}>Cards para redes</button>\n        <span className=\"db-marca\">{NOMBRE_MEDIO}</span>\n      </div>\n\n      {vista === 'editor' && <Editor articulos={articulos} secciones={secciones} />}\n\n      {vista === 'cards' && (\n        <div className=\"db-cards\">\n          <div className=\"db-cardTipos\">\n            {([\n              ['dato', 'El dato'],\n              ['cita', 'La cita'],\n              ['ultimahora', 'Última hora'],\n              ['claves', 'Las claves'],\n            ] as [TipoCard, string][]).map(([k, l]) => (\n              <button key={k} className={'db-cardTipo' + (tipoCard === k ? ' activo' : '')} onClick={() => setTipoCard(k)}>{l}</button>\n            ))}\n          </div>\n          {tipoCard === 'dato' && <CardDato esMovil={esMovil} nombreMedio={NOMBRE_MEDIO} />}\n          {tipoCard === 'cita' && <CardCita esMovil={esMovil} nombreMedio={NOMBRE_MEDIO} />}\n          {tipoCard === 'ultimahora' && <CardUltimaHora esMovil={esMovil} nombreMedio={NOMBRE_MEDIO} />}\n          {tipoCard === 'claves' && <CardClaves esMovil={esMovil} nombreMedio={NOMBRE_MEDIO} />}\n        </div>\n      )}\n    </div>\n  );\n}\n" },
  { path: "src/components/Dashboard/dashboard.css", content: ".db-root { background: var(--fondo); color: var(--tinta); min-height: 100vh; font-family: var(--ui); }\n\n.db-tabs {\n  display: flex; align-items: center; gap: 6px; padding: 10px 18px;\n  background: var(--panel); border-bottom: 1px solid var(--regla);\n  position: sticky; top: 0; z-index: 60;\n}\n.db-tab {\n  background: transparent; border: 1px solid var(--regla); border-radius: 999px;\n  color: var(--tinta-suave); font-family: var(--ui); font-size: 13px; font-weight: 700;\n  padding: 8px 16px; cursor: pointer;\n}\n.db-tab.activo { background: var(--primario); border-color: var(--primario); color: var(--fondo); }\n.db-marca { margin-left: auto; font-family: var(--mono); font-size: 12px; color: var(--tinta-suave); }\n\n.db-cards { max-width: 900px; margin: 0 auto; padding: 20px; }\n.db-cardTipos { display: flex; gap: 6px; margin-bottom: 16px; flex-wrap: wrap; }\n.db-cardTipo {\n  background: var(--panel); border: 1px solid var(--regla); border-radius: 9px;\n  color: var(--tinta-suave); font-family: var(--ui); font-size: 12px; font-weight: 600;\n  padding: 8px 14px; cursor: pointer;\n}\n.db-cardTipo.activo { border-color: var(--primario); color: var(--primario); background: color-mix(in srgb, var(--primario) 12%, transparent); }\n" },
  ];
}
